    'qr.features.noWatermark.title': 'No Watermark',
    'qr.features.noWatermark.desc': 'Your QR codes are clean and professional. Unlike competitors, we never add watermarks to free QR codes.',
    'qr.features.noExpiration.title': 'No Expiration',
    'qr.features.noExpiration.desc': 'Static QR codes work forever. No trial periods, no expiration dates, no surprise paywalls after 14 days.',
    'qr.features.privacyFirst.title': 'Privacy-First',
