    // FAQ
    'qr.faq.heading': 'Frequently Asked Questions',
    'qr.faq.q1': 'Is this QR code generator really free?',
    'qr.faq.a1': 'Yes, completely free with no hidden costs. No signup required, no premium tiers, no ads. Every feature — including SVG export and customization — is available at no charge.',
    'qr.faq.q2': 'Do the QR codes expire?',
    'qr.faq.a2': 'No. This generator creates static QR codes that work forever. Some competitors offer "dynamic" QR codes that expire after a trial period and then charge you — we don\'t do that. Your QR code will always work.',
    'qr.faq.q3': 'Is my data sent to any servers?',
    'qr.faq.a3': 'No. The QR code is generated entirely in your browser using JavaScript. Your URLs, WiFi passwords, contacts, and text never leave your device. We have zero access to your data.',
    'qr.faq.q4': 'What types of QR codes can I create?',
    'qr.faq.a4': 'You can generate QR codes for URLs (links to websites), WiFi credentials (so guests can connect with a scan), vCard contact cards (digital business cards), and plain text. More types coming soon.',
    'qr.faq.q5': 'Can I customize the colors of my QR code?',
    'qr.faq.a5': 'Yes! You can choose any foreground and background color. We recommend maintaining high contrast for reliable scanning. Dark foreground on light background works best.',
    'qr.faq.q6': 'What is error correction and which level should I choose?',
    'qr.faq.a6': 'Error correction allows a QR code to be read even if partially damaged or obscured. Level L recovers 7% of data, M recovers 15%, Q recovers 25%, and H recovers 30%. Higher levels create denser QR codes. For most uses, M is the best balance. Choose H if you plan to add a logo overlay.',

