    'wl.seo.what.heading': 'What Is a WhatsApp Link?',
    'wl.seo.what.text': 'A WhatsApp link (also called a click-to-chat link) uses the official wa.me protocol to let anyone start a conversation with you on WhatsApp in one click — without saving your number first. When someone clicks your link, WhatsApp opens with a pre-filled message ready to send. It works on any device, any browser, anywhere in the world. Businesses put these links in Instagram bios, on websites, in email signatures, on printed flyers, and even in QR codes at physical locations. OPN Chat generates these links for free, entirely in your browser — nothing is stored on any server.',
    'wl.seo.why.heading': 'Why Create a WhatsApp Link?',
    'wl.seo.why.feature1.title': 'One-Click Contact',
    'wl.seo.why.feature1.desc': 'Your customers or contacts can reach you instantly. No saving numbers, no searching — just click and start chatting.',
    'wl.seo.why.feature2.title': 'Pre-filled Messages',
    'wl.seo.why.feature2.desc': 'Add a default message so people know exactly what to say when they contact you. Great for business inquiries and order tracking.',
    'wl.seo.why.feature3.title': 'QR Code Included',
    'wl.seo.why.feature3.desc': 'Every link comes with a free QR code. Print it on business cards, menus, storefronts — scan and chat instantly.',
    'wl.seo.why.feature4.title': 'Works Everywhere',
    'wl.seo.why.feature4.desc': 'Put your link in Instagram bio, Facebook, Twitter, email signature, website, WhatsApp Business catalog — anywhere people can click.',
    'wl.seo.how.heading': 'How It Works',
    'wl.seo.how.text': 'Creating a WhatsApp link with OPN Chat takes less than a minute. Enter your phone number with country code, optionally write a pre-filled message that users will see when they open the chat, and click "Generate." You get a wa.me link like https://wa.me/15551234567?text=Hello that you can copy, share, and embed in a QR code. No registration, no server storage, everything happens in your browser.',
    'wl.seo.use.heading': 'Where to Use Your WhatsApp Link',
    'wl.seo.use.text': 'WhatsApp links are incredibly versatile. Put them in your Instagram bio — it is one of the most common places. Add them to your website contact page so visitors can message you directly. Include them in email signatures for quick follow-ups. Print QR codes on business cards, restaurant menus, event flyers, or delivery packaging. Embed them in Facebook ads to convert clicks into conversations. Use them in WhatsApp Business catalogs for product inquiries. The possibilities are endless — anywhere someone might want to reach you on WhatsApp.',
    'wl.seo.faq.heading': 'Frequently Asked Questions',
    'wl.seo.faq.q1': 'Is it free to create a WhatsApp link?',
    'wl.seo.faq.a1': 'Yes, completely free. OPN Chat generates wa.me links at no cost, with no limits, no registration, and no ads. The links work forever — they are based on WhatsApp official protocol.',
    'wl.seo.faq.q2': 'What is the pre-filled message?',
    'wl.seo.faq.a2': 'The pre-filled message is a default text that appears in the chat input when someone opens your link. It makes it easier for people to start a conversation and helps you know where they came from. For example: "Hello, I want to know more about your services."',
    'wl.seo.faq.q3': 'Does the other person need my number saved?',
    'wl.seo.faq.a3': 'No. When someone clicks your wa.me link, WhatsApp opens a chat with your number regardless of whether they have it saved. However, if you have privacy settings restricting messages from unknown contacts, they may need to add your number first.',
    'wl.seo.faq.q4': 'Can I change the link later?',
    'wl.seo.faq.a4': 'The wa.me link structure is fixed (wa.me/COUNTRYCODE+NUMBER). If you change your number, you need to generate a new link. The pre-filled message can be changed at any time by generating a new link with a different message.',
    'wl.seo.faq.q5': 'Does this work in my country?',
    'wl.seo.faq.a5': 'Yes, wa.me links work in every country where WhatsApp is officially available. OPN Chat simply generates the link — the actual chat happens through WhatsApp itself, using their official protocol.',

