    'tgl.share.label': 'Share your link',
    'tgl.preview.label': 'This is how your users will see it',
    'tgl.seo.what.heading': 'What Is a Telegram Link?',
    'tgl.seo.what.text': 'A Telegram link (also called a t.me link) uses the official Telegram protocol to let anyone start a conversation with your bot, channel, or personal account in one click. When you add the ?start= parameter, users who click the link will see a pre-filled message ready to send. It works on any device, any browser, anywhere in the world. Businesses put these links in Instagram bios, on websites, in email signatures, on printed flyers, and even in QR codes at physical locations. OPN Chat generates these links for free, entirely in your browser — nothing is stored on any server.',
    'tgl.seo.why.heading': 'Why Create a Telegram Link?',
    'tgl.seo.why.feature1.title': 'One-Click Contact',
    'tgl.seo.why.feature1.desc': 'Your customers or contacts can reach you instantly on Telegram. No searching, no adding contacts — just click and start chatting.',
    'tgl.seo.why.feature2.title': 'Start Messages',
    'tgl.seo.why.feature2.desc': 'Add a default start message so people know exactly what to say when they contact you. Great for business inquiries, customer support, and onboarding.',
    'tgl.seo.why.feature3.title': 'QR Code Included',
    'tgl.seo.why.feature3.desc': 'Every link comes with a free QR code. Print it on business cards, menus, storefronts — scan and chat instantly on Telegram.',
    'tgl.seo.why.feature4.title': 'Works Everywhere',
    'tgl.seo.why.feature4.desc': 'Put your link in Instagram bio, Facebook, Twitter, email signature, website — anywhere people can click. Telegram is available globally on all platforms.',
    'tgl.seo.how.heading': 'How It Works',
    'tgl.seo.how.text': 'Creating a Telegram link with OPN Chat takes less than a minute. Enter your Telegram username (without the @ symbol), optionally write a start message that users will see when they open the chat, and click "Generate." You get a t.me link like https://t.me/your_business?start=Hello that you can copy, share, and embed in a QR code. No registration, no server storage, everything happens in your browser.',
    'tgl.seo.use.heading': 'Where to Use Your Telegram Link',
    'tgl.seo.use.text': 'Telegram links are incredibly versatile. Put them in your Instagram bio — it is one of the most common places. Add them to your website contact page so visitors can message you directly on Telegram. Include them in email signatures for quick follow-ups. Print QR codes on business cards, restaurant menus, event flyers, or delivery packaging. Embed them in Facebook ads to convert clicks into Telegram conversations. Use them for Telegram bots so users can start with a specific command. The possibilities are endless — anywhere someone might want to reach you on Telegram.',
    'tgl.seo.faq.heading': 'Frequently Asked Questions',
    'tgl.seo.faq.q1': 'Is it free to create a Telegram link?',
    'tgl.seo.faq.a1': 'Yes, completely free. OPN Chat generates t.me links at no cost, with no limits, no registration, and no ads. The links work forever — they are based on Telegram official protocol.',
    'tgl.seo.faq.q2': 'What is the start message?',
    'tgl.seo.faq.a2': 'The start message is a default text that appears in the chat input when someone opens your Telegram link. It makes it easier for people to start a conversation and helps you know what they want. For example: "Hello, I want to know more about your services." This is especially useful for Telegram bots.',
    'tgl.seo.faq.q3': 'Does the other person need to know my username?',
    'tgl.seo.faq.a3': 'No. When someone clicks your t.me link, Telegram opens a chat with your account or bot regardless of whether they know your username. The link works as a direct gateway to start a conversation.',
    'tgl.seo.faq.q4': 'Can I change the link later?',
    'tgl.seo.faq.a4': 'The t.me link structure is fixed (t.me/USERNAME). If you change your username, you need to generate a new link. The start message can be changed at any time by generating a new link with a different message.',
    'tgl.seo.faq.q5': 'Does this work for bots and channels too?',
    'tgl.seo.faq.a5': 'Yes! t.me links work for personal accounts, bots, and channels. For bots, the ?start= parameter is especially powerful — it lets users start your bot with a specific command, which is great for onboarding and customer support workflows.',
    'tgl.linktype.label': 'Link type',
