    'wc.meta.title': 'Word & Character Counter — Free & Private | OPN Chat',
    'wc.meta.description': 'Count words, characters, sentences, and reading time instantly. Analyze keyword density for SEO. 100% private — your text never leaves your browser. Free, no sign-up.',
