    'fmt.meta.title': 'WhatsApp Text Formatter — Bold, Italic, Strikethrough, Monospace | OPN Chat',
    'fmt.meta.description': 'Free WhatsApp text formatter. Add bold, italic, strikethrough, and monospace formatting to your WhatsApp messages with live preview. Copy and paste directly. No sign-up, 100% private.',
    'fmt.meta.keywords': 'whatsapp text formatter, whatsapp bold, whatsapp italic, whatsapp strikethrough, whatsapp monospace, whatsapp formatting, format whatsapp message, whatsapp text style',
    'fmt.meta.og.title': 'WhatsApp Text Formatter — Bold, Italic, Strikethrough, Monospace',
    'fmt.meta.og.description': 'Format WhatsApp messages with bold, italic, strikethrough, and monospace. Live preview, one-click copy. Free and private.',
    'fmt.meta.twitter.title': 'WhatsApp Text Formatter — Bold, Italic, Strikethrough',
    'fmt.meta.twitter.description': 'Format WhatsApp messages instantly. Bold, italic, strikethrough, monospace. Free, private, no sign-up.',
    'fmt.seo.what.heading': 'What Is WhatsApp Text Formatting?',
    'fmt.seo.what.text': 'WhatsApp supports four text formatting styles: bold, italic, strikethrough, and monospace. Each style uses special characters wrapped around your text — asterisks for bold, underscores for italic, tildes for strikethrough, and triple backticks for monospace. OPN Chat\'s Text Formatter makes this easy: select the style you want, type your message, and the tool automatically wraps your text with the correct formatting characters. You get a live WhatsApp-style preview so you can see exactly how your message will look before sending it.',
    'fmt.seo.formats.heading': 'WhatsApp Formatting Codes',
    'fmt.seo.formats.bold.example': 'bold text',
    'fmt.seo.formats.italic.example': 'italic text',
    'fmt.seo.formats.strikethrough.example': 'strikethrough text',
    'fmt.seo.formats.monospace.example': 'monospace text',
    'fmt.seo.why.heading': 'Why Use OPN Chat\'s Text Formatter?',
    'fmt.seo.why.feature1.title': 'One-Click Formatting',
    'fmt.seo.why.feature1.desc': 'No need to remember formatting codes. Click a button and your text is wrapped automatically with the correct markers.',
    'fmt.seo.why.feature2.title': 'Live WhatsApp Preview',
    'fmt.seo.why.feature2.desc': 'See exactly how your formatted message will appear in WhatsApp before you copy it. No surprises.',
    'fmt.seo.why.feature3.title': '100% Private',
    'fmt.seo.why.feature3.desc': 'Your text never leaves your browser. No data is sent to any server. Everything runs locally.',
    'fmt.seo.why.feature4.title': 'Works Everywhere',
    'fmt.seo.why.feature4.desc': 'Use formatted text in WhatsApp, WhatsApp Business, WhatsApp Web, and WhatsApp Desktop. The formatting codes are universal.',
    'fmt.seo.how.heading': 'How to Use It',
    'fmt.seo.how.text': 'Select the formatting style you want (bold, italic, strikethrough, or monospace) by clicking the corresponding button. Type your message in the input field. The formatted text appears in the output area with the correct WhatsApp markers, and a live preview shows how it will look in a real WhatsApp chat. Click Copy to copy the formatted text, then paste it directly into WhatsApp.',
    'fmt.faq.heading': 'Frequently Asked Questions',
    'fmt.faq.q1': 'How do I format text in WhatsApp manually?',
    'fmt.faq.a1': 'Wrap your text with special characters: *bold*, _italic_, ~strikethrough~, and ```monospace```. OPN Chat does this automatically so you don\'t have to remember the codes.',
    'fmt.faq.q2': 'Can I combine multiple formatting styles?',
    'fmt.faq.a2': 'Yes! You can select multiple format buttons at the same time. For example, bold + italic will produce *_bold italic_* which renders as bold and italic simultaneously in WhatsApp.',
    'fmt.faq.q3': 'Does this work in WhatsApp Business?',
    'fmt.faq.a3': 'Yes. WhatsApp formatting codes work identically in WhatsApp, WhatsApp Business, WhatsApp Web, and WhatsApp Desktop. They are part of the official WhatsApp protocol.',
    'fmt.faq.q4': 'Is OPN Chat Text Formatter free?',
    'fmt.faq.a4': 'Completely free. No hidden fees, no premium tiers, no ads. Everything runs in your browser with zero data collection.',
    'fmt.faq.q5': 'Will the recipient see the formatting?',
    'fmt.faq.a5': 'Yes, as long as the recipient is using a recent version of WhatsApp, they will see your message with the formatting applied. Older versions may display the raw markers instead.',
    'fmt.footer.tagline': 'opnchat.net — WhatsApp Text Formatter. No data on servers. Everything runs in your browser.',
    'fmt.footer.disclaimer': 'OPN Chat is not affiliated with Meta or WhatsApp.',
