    'cw.seo.what.heading': 'What Is a WhatsApp Chat Widget?',
    'cw.seo.what.text': 'A WhatsApp Chat Widget is a floating button or popup that appears on your website, allowing visitors to start a WhatsApp conversation with you in one click. When a visitor clicks the widget, WhatsApp opens with a pre-filled message ready to send — no need to save your phone number first. The widget typically appears as a small circular button in the corner of your website that expands into a chat popup with a welcome message. OPN Chat Widget Generator lets you create this widget for free, customize its appearance and behavior, and get a ready-to-use HTML code snippet that you can embed on any website or platform.',
    'cw.seo.why.heading': 'Why Add a WhatsApp Widget to Your Website?',
    'cw.seo.why.feature1.title': 'Instant Customer Contact',
    'cw.seo.why.feature1.desc': 'Visitors can reach you with one click. No phone number to save, no contact form to fill — just click and start chatting on WhatsApp immediately.',
    'cw.seo.why.feature2.title': 'Fully Customizable',
    'cw.seo.why.feature2.desc': 'Choose the widget color, position, welcome message, and button text. Make it match your brand perfectly. Every detail is configurable.',
    'cw.seo.why.feature3.title': '100% Free & Private',
    'cw.seo.why.feature3.desc': 'No monthly fees, no premium tiers, no data collection. The widget code is generated entirely in your browser and runs on your website independently.',
    'cw.seo.why.feature4.title': 'Works on Any Website',
    'cw.seo.why.feature4.desc': 'Copy the HTML code and paste it into WordPress, Shopify, Wix, Squarespace, Blogger, or any custom website. No plugins or extensions needed.',
    'cw.seo.how.heading': 'How It Works',
    'cw.seo.how.text': 'Creating a WhatsApp chat widget with OPN Chat takes less than a minute. Enter your WhatsApp phone number with country code, optionally add a pre-filled message for visitors, choose the widget position (left or right corner), pick a color that matches your brand, write a welcome message that appears in the popup, and set the button label text. Click "Generate Widget Code" and you get a complete HTML snippet. Copy it, paste it into the HTML of your website before the closing body tag, and the widget appears on your site immediately. No registration, no server storage, everything happens in your browser.',
    'cw.seo.use.heading': 'Where to Use Your WhatsApp Widget',
    'cw.seo.use.text': 'WhatsApp chat widgets are perfect for any website that wants to make customer communication easy. E-commerce stores on Shopify or WooCommerce use them for product inquiries and order support. Service businesses like dentists, lawyers, and real estate agents place them on landing pages so potential clients can ask questions instantly. Restaurants and cafes embed them on their websites for reservation requests. Hotels and travel agencies use them for booking confirmations and guest inquiries. WordPress blogs and portfolio sites add them for reader engagement. The widget works on every platform that allows custom HTML — just paste the code and your visitors can reach you on WhatsApp immediately.',
    'cw.faq.heading': 'Frequently Asked Questions',
    'cw.faq.q1': 'Is the WhatsApp widget free?',
    'cw.faq.a1': 'Yes, completely free. OPN Chat generates the widget code at no cost, with no limits, no registration, and no ads. The code runs on your website independently — there are no external dependencies or monthly fees.',
    'cw.faq.q2': 'Do I need to install a plugin?',
    'cw.faq.a2': 'No. You just copy the HTML code snippet and paste it into your website. It works on WordPress, Shopify, Wix, Squarespace, Blogger, and any custom website that allows HTML editing. No plugins, extensions, or server-side setup required.',
    'cw.faq.q3': 'Can I customize the widget appearance?',
    'cw.faq.a3': 'Yes. You can choose the widget position (left or right corner), the button color, the welcome message text, and the button label. All customization happens in the generator, and the final code reflects your choices exactly.',
    'cw.faq.q4': 'Will the widget work on mobile devices?',
    'cw.faq.a4': 'Yes. On mobile devices, clicking the widget opens the WhatsApp app directly. On desktop, it opens WhatsApp Web. The widget automatically adapts to the device of the visitor for the best experience.',
    'cw.faq.q5': 'Does the widget collect any data?',
    'cw.faq.a5': 'No. The widget code generated by OPN Chat is purely client-side HTML, CSS, and JavaScript. It does not send any data to OPN Chat or any third-party server. When a visitor clicks the widget, they go directly to WhatsApp using the official wa.me protocol.',
    'cw.footer.tagline': 'opnchat.net — WhatsApp Chat Widget Generator. No data on servers. Everything runs in your browser.',
    'cw.footer.disclaimer': 'OPN Chat is not affiliated with Meta or WhatsApp.',
