    'ep.privacy.badge': '100% Private — All emoji browsing runs in your browser, no data sent',
    'ep.meta.title': 'Emoji Picker & Keyboard — Copy Emojis for WhatsApp, Telegram & Social Media | OPN Chat',
    'ep.meta.description': 'Free emoji picker and keyboard for WhatsApp, Telegram, Instagram, and social media. Search emojis by category or keyword, copy instantly. 9 categories, 500+ emojis, no sign-up, 100% private.',
    'ep.meta.keywords': 'emoji picker, emoji keyboard, emoji search, copy emoji, whatsapp emoji, telegram emoji, emoji catalog, emoji finder, online emoji picker, free emoji, emoji for whatsapp, emoji for telegram, opnchat',
    'ep.meta.og.title': 'Emoji Picker & Keyboard — Copy Emojis Instantly',
    'ep.meta.og.description': 'Search and copy emojis for WhatsApp, Telegram, and social media. 9 categories, keyword search, instant copy. Free & private.',
    'ep.meta.twitter.title': 'Emoji Picker & Keyboard — Free Emoji Search',
    'ep.meta.twitter.description': 'Find and copy emojis for WhatsApp, Telegram, Instagram. 9 categories, keyword search. Free & private.',
    'ep.search.placeholder': 'Search emojis (e.g. heart, cat, fire)...',
