    'ep.recent.heading': 'Recently Used',
    'ep.copied': 'Copied!',
    'ep.seo.what.heading': 'What Is an Emoji Picker?',
    'ep.seo.what.text': 'An Emoji Picker (also called an Emoji Keyboard) is a free online tool that lets you search, browse, and copy any emoji character directly to your clipboard. Unlike the built-in emoji picker on your phone or computer, which is limited to the apps you are currently using, OPN Chat Emoji Picker works in any browser on any device. You simply find the emoji you want by browsing categories or typing a keyword, click it, and it is instantly copied to your clipboard — ready to paste into WhatsApp, Telegram, Instagram, Twitter/X, TikTok, email, or any text field. The catalog includes over 500 emojis organized into 9 categories, each searchable by name and keyword.',
    'ep.seo.why.heading': 'Why Use an Online Emoji Picker?',
    'ep.seo.why.feature1.title': 'Search by Keyword',
    'ep.seo.why.feature1.desc': 'Type "heart", "cat", or "fire" and find the perfect emoji instantly. No need to scroll through hundreds of emojis — the search filters across all 9 categories simultaneously, showing you every emoji that matches your query.',
    'ep.seo.why.feature2.title': 'Copy & Paste Anywhere',
    'ep.seo.why.feature2.desc': 'One click copies the emoji to your clipboard. Paste it directly into WhatsApp messages, Telegram chats, Instagram bios and captions, Twitter/X posts, TikTok comments, or any platform. Emojis are standard Unicode characters, so they work everywhere.',
    'ep.seo.why.feature3.title': '100% Private',
    'ep.seo.why.feature3.desc': 'OPN Chat Emoji Picker runs entirely in your browser. No emoji selections are uploaded, no data is stored on any server, and no cookies are used for tracking. Your emoji browsing history is saved locally in your browser only for convenience — you can clear it anytime.',
    'ep.seo.why.feature4.title': 'Works on Any Device',
    'ep.seo.why.feature4.desc': 'The emoji picker works on phones, tablets, and computers. On mobile, it replaces the limited built-in emoji keyboard with a searchable catalog. On desktop, it gives you emoji access when your keyboard does not have an emoji picker built in. No app installation required.',
    'ep.seo.how.heading': 'How Does the Emoji Picker Work?',
    'ep.seo.how.text': 'Using the OPN Chat Emoji Picker is simple. Browse emojis by clicking one of the 9 category tabs (Smileys, People, Animals, Food, Activities, Travel, Objects, Symbols, Flags), or type a keyword in the search field to find emojis across all categories. When you see the emoji you want, click it — the emoji is instantly copied to your clipboard and a brief notification confirms the copy. Paste it into any app or text field. Your recently used emojis are saved locally in your browser so you can quickly find them again next time.',
    'ep.seo.faq.heading': 'Frequently Asked Questions',
    'ep.faq.q1': 'Do emojis work on WhatsApp and Telegram?',
    'ep.faq.a1': 'Yes! All emojis in this picker are standard Unicode characters, which WhatsApp, Telegram, Instagram, Twitter/X, TikTok, Facebook, SMS, email, and virtually every platform supports. When you copy an emoji from OPN Chat and paste it into WhatsApp or Telegram, it appears exactly as intended on both your device and the recipient device.',
    'ep.faq.q2': 'Is the emoji picker free?',
    'ep.faq.a2': 'Completely free. No sign-up, no premium tiers, no ads, no limits. Browse and copy as many emojis as you want — the tool is available to everyone without any restrictions. All processing happens in your browser with zero server interaction.',
    'ep.faq.q3': 'Does OPN Chat track my emoji selections?',
    'ep.faq.a3': 'No. OPN Chat does not upload, log, or track any emoji selections. Your recently used emojis are saved only in your browser localStorage for convenience, so you can quickly access them again. You can clear this history anytime by clearing your browser data. No information is sent to our servers.',
    'ep.faq.q4': 'How many emojis are available?',
    'ep.faq.a4': 'OPN Chat Emoji Picker includes over 500 emojis across 9 categories: Smileys & Emotions (60+), People & Body (70+), Animals & Nature (70+), Food & Drink (80+), Activities & Sports (60+), Travel & Places (80+), Objects (100+), Symbols (90+), and Flags (80+). The catalog covers the most commonly used emojis for messaging and social media.',
    'ep.faq.q5': 'Can I search emojis by keyword?',
    'ep.faq.a5': 'Yes! Type any keyword in the search field — for example "heart", "cat", "fire", "happy", "food", "car" — and the picker filters all emojis across every category that match. Each emoji has multiple keywords assigned, so even if you do not know the exact emoji name, a related word will find it.',
    'footer.emojipicker.link': 'Emoji Picker',

