    'cv.features.heading': '¿Por Qué Usar Nuestro Convertidor?',
    'cv.features.instant.title': 'Conversión Instantánea',
    'cv.features.instant.desc': 'Los resultados aparecen mientras escribes. Sin carga, sin esperas. Soporta más de 50 pares de unidades en 7 categorías — desde necesidades cotidianas como cm a pulgadas hasta unidades especializadas como millas náuticas.',
    'cv.features.private.title': '100% Privado y Sin Conexión',
    'cv.features.private.desc': 'Todos los cálculos se realizan en tu navegador. No se envían datos a ningún servidor. Funciona sin conexión después de la primera carga — perfecto para viajar cuando no tienes internet.',
    'cv.features.offline.title': 'Funciona en Todas Partes',
    'cv.features.offline.desc': 'Úsalo en tu teléfono, tablet o computadora. El diseño responsivo se adapta a cualquier pantalla. Sin instalación — solo un marcador y estarás listo para convertir.',
    'cv.features.everyday.title': 'Lo Esencial de Cada Día',
    'cv.features.everyday.desc': 'Las conversiones que más se buscan: cm a pulgadas, kg a libras, km a millas, Fahrenheit a Celsius. Además de medidas de cocina, almacenamiento de datos, área de terreno y unidades de velocidad.',

    'cv.faq.heading': 'Preguntas Frecuentes',
    'cv.faq.q1': '¿Qué tan precisas son las conversiones?',
    'cv.faq.a1': 'Nuestras conversiones usan fórmulas matemáticas precisas con aritmética de punto flotante de alta precisión. Para uso cotidiano (cocina, viajes, bricolaje), la precisión es más que suficiente. Mostramos hasta 8 dígitos significativos para trabajos que requieren precisión.',
    'cv.faq.q2': '¿Funciona sin conexión a internet?',
    'cv.faq.a2': '¡Sí! Después de la primera carga, el convertidor funciona completamente sin conexión porque todos los cálculos se ejecutan en JavaScript en tu navegador. No se realizan llamadas al servidor durante la conversión. Esto lo hace perfecto para viajar cuando no tienes acceso a internet.',
    'cv.faq.q3': '¿Qué categorías de unidades están disponibles?',
    'cv.faq.a3': 'Soportamos 7 categorías: Longitud (mm, cm, m, km, in, ft, yd, mi, nmi), Peso (mg, g, kg, t, oz, lb, st), Temperatura (Celsius, Fahrenheit, Kelvin), Volumen (mL, L, fl oz, taza, pinta, cuarto, galón, cucharada, cucharadita), Velocidad (m/s, km/h, mph, nudos, ft/s), Área (cm2, m2, km2, hectáreas, ft2, acres, mi2) y Datos (Bytes, KB, MB, GB, TB, bits, Kbit, Mbit).',
    'cv.faq.q4': '¿Se envían mis datos a algún servidor?',
    'cv.faq.a4': 'No. Todas las conversiones se calculan localmente en tu navegador usando JavaScript. Ningún valor, selección de unidad o historial de conversión se envía a nuestros servidores o terceros. Tus cálculos son completamente privados.',
    'cv.faq.q5': '¿Por qué usar esto en lugar de Google?',
    'cv.faq.a5': 'Google requiere conexión a internet y rastrea tus búsquedas. Nuestro convertidor funciona sin conexión, respeta tu privacidad sin rastreo, y ofrece una interfaz dedicada con funciones de intercambio, copia y referencia rápida que Google no ofrece. Además, nuestra PWA se puede instalar en tu pantalla de inicio.',

