    'np.features.heading': '¿Por qué usar OPN Notepad?',
    'np.features.local.title': '100% Almacenamiento Local',
    'np.features.local.desc': 'Tus notas se guardan en el localStorage de tu navegador. Sin nube, sin servidor, sin cuenta. Tus datos nunca salen de tu dispositivo.',
    'np.features.instant.title': 'Instantáneo y Rápido',
    'np.features.instant.desc': 'Sin pantallas de carga, sin esperas. Abre la página y empieza a escribir. El autoguardado asegura que nunca pierdas tu trabajo.',
    'np.features.private.title': 'Completamente Privado',
    'np.features.private.desc': 'Sin rastreo, sin analíticas, sin recopilación de datos. Lo que escribes se queda entre tú y tu navegador. Punto.',
    'np.features.free.title': 'Gratis Para Siempre',
    'np.features.free.desc': 'Sin planes premium, sin anuncios, sin registros. Solo un bloc de notas limpio y simple que funciona en cualquier dispositivo.',

    'np.faq.heading': 'Preguntas Frecuentes',
    'np.faq.q1': '¿Dónde se guardan mis notas?',
    'np.faq.a1': 'Tus notas se guardan en el localStorage de tu navegador. Esto significa que se almacenan solo en tu dispositivo. Si limpias los datos del navegador o usas uno diferente, tus notas no estarán disponibles allí.',
    'np.faq.q2': '¿Puedo acceder a mis notas desde otro dispositivo?',
    'np.faq.a2': 'No, como las notas se guardan localmente en tu navegador, no se pueden acceder desde otro dispositivo. Esto es una función de privacidad — tus datos nunca salen de tu dispositivo. Si necesitas transferir notas, usa la función Exportar para guardarlas como archivo de texto.',
    'np.faq.q3': '¿Perderé mis notas si cierro el navegador?',
    'np.faq.a3': 'No, tus notas se guardan automáticamente en localStorage mientras escribes. Estarán ahí cuando vuelvas. Sin embargo, si limpias los datos locales de tu navegador o usas el modo incógnito, las notas se perderán.',
    'np.faq.q4': '¿Hay un límite de notas que puedo crear?',
    'np.faq.a4': 'localStorage generalmente permite 5-10 MB por sitio web, lo que es suficiente para miles de notas de texto. Si alcanzas el límite, puedes exportar las notas más antiguas y eliminarlas para liberar espacio.',
    'np.faq.q5': '¿Puedo exportar mis notas?',
    'np.faq.a5': '¡Sí! Haz clic en el botón Exportar para descargar todas tus notas como archivo de texto plano. También puedes copiar notas individuales al portapapeles.',

