    'pw.features.heading': '¿Por Qué Usar Nuestro Generador?',
    'pw.features.crypto.title': 'Criptográficamente Seguro',
    'pw.features.crypto.desc': 'Usa crypto.getRandomValues() — el mismo estándar de aleatoriedad usado en cifrado. No Math.random().',
    'pw.features.local.title': '100% Procesamiento Local',
    'pw.features.local.desc': 'Tus contraseñas se generan en tu navegador y nunca se envían a ningún lado. Cero participación del servidor.',
    'pw.features.custom.title': 'Totalmente Personalizable',
    'pw.features.custom.desc': 'Controla la longitud, tipos de caracteres y genera múltiples contraseñas a la vez. Tus reglas, tus contraseñas.',
    'pw.features.free.title': 'Gratis y Sin Registro',
    'pw.features.free.desc': 'Sin cuenta, sin límites, sin anuncios. Solo abre y genera. Funciona en cualquier dispositivo.',

    'pw.faq.heading': 'Preguntas Frecuentes',
    'pw.faq.q1': '¿Es realmente seguro este generador de contraseñas?',
    'pw.faq.a1': 'Sí. Usamos la API Web Crypto (crypto.getRandomValues()), que proporciona números aleatorios criptográficamente seguros. Es el mismo estándar usado para cifrado y certificados de seguridad. A diferencia de Math.random(), no se puede predecir.',
    'pw.faq.q2': '¿Se almacenan mis contraseñas generadas en algún lugar?',
    'pw.faq.a2': 'No. Todas las contraseñas se generan completamente en tu navegador usando JavaScript. No se envía nada a nuestros servidores ni a ningún servicio externo. Al cerrar o actualizar la página, las contraseñas generadas desaparecen.',
    'pw.faq.q3': '¿Qué tan larga debe ser mi contraseña?',
    'pw.faq.a3': 'Recomendamos al menos 16 caracteres para una seguridad fuerte. Para cuentas de alta seguridad (banca, correo), usa 20+ caracteres con todos los tipos de caracteres habilitados. Cada carácter adicional aumenta exponencialmente las combinaciones posibles.',
    'pw.faq.q4': '¿Qué hace que una contraseña sea fuerte?',
    'pw.faq.a4': 'Una contraseña fuerte combina longitud (12+ caracteres), aleatoriedad (no una palabra del diccionario) y variedad (mayúsculas, minúsculas, números y símbolos). Nuestro medidor de fortaleza mide la entropía — la medida matemática de imprevisibilidad — para darte una evaluación precisa.',
    'pw.faq.q5': '¿Puedo generar múltiples contraseñas a la vez?',
    'pw.faq.a5': '¡Sí! Usa la sección "Generar por Lote" para crear hasta 10 contraseñas a la vez. Puedes copiarlas todas con un clic.',
    'pw.faq.q6': '¿Qué es la entropía y por qué importa?',
    'pw.faq.a6': 'La entropía mide la imprevisibilidad de una contraseña en bits. Mayor entropía significa más combinaciones posibles que un atacante tendría que probar. Una contraseña con 80+ bits de entropía se considera muy fuerte. Nuestro generador te muestra la entropía en tiempo real.',

