    'tgl.share.label': 'Comparte tu enlace',
    'tgl.preview.label': 'Asi veran tu enlace tus usuarios',
    'tgl.seo.what.heading': 'Que Es un Enlace de Telegram?',
    'tgl.seo.what.text': 'Un enlace de Telegram (t.me) usa el protocolo oficial de Telegram para que cualquier persona pueda iniciar una conversacion con tu bot, canal o cuenta personal en un solo clic. Cuando agregas el parametro ?start=, los usuarios que clickeen el enlace vera un mensaje predefinido listo para enviar. Funciona en cualquier dispositivo, navegador y pais. Las empresas ponen estos enlaces en bios de Instagram, sitios web, firmas de correo, flyers impresos y QR codes. OPN Chat genera estos enlaces gratis, completamente en tu navegador — nada se almacena en ningun servidor.',
    'tgl.seo.why.heading': 'Por Que Crear un Enlace de Telegram?',
    'tgl.seo.why.feature1.title': 'Contacto en Un Clic',
    'tgl.seo.why.feature1.desc': 'Tus clientes o contactos pueden comunicarse con usted en Telegram al instante. Sin buscar, sin agregar contactos — solo clic y chatear.',
    'tgl.seo.why.feature2.title': 'Mensaje de Inicio',
    'tgl.seo.why.feature2.desc': 'Agrega un mensaje de inicio predeterminado para que las personas sepan que decir al contactarte. Ideal para consultas de negocio y atencion al cliente.',
    'tgl.seo.why.feature3.title': 'Codigo QR Incluido',
    'tgl.seo.why.feature3.desc': 'Cada enlace viene con un codigo QR gratis. Imprimelo en tarjetas de presentacion, menus, tiendas — escanea y chatea al instante.',
    'tgl.seo.why.feature4.title': 'Funciona en Todo Lugar',
    'tgl.seo.why.feature4.desc': 'Pon tu enlace en bio de Instagram, Facebook, Twitter, firma de correo, sitio web — donde alguien pueda clickear. Telegram esta disponible globalmente.',
    'tgl.seo.how.heading': 'Como Funciona',
    'tgl.seo.how.text': 'Crear un enlace de Telegram con OPN Chat toma menos de un minuto. Ingresa tu nombre de usuario de Telegram (sin el @), opcionalmente escribe un mensaje de inicio, y haz clic en "Generar." Obtienes un enlace t.me como https://t.me/tu_negocio?start=Hola que puedes copiar, compartir y convertir en QR. Sin registro, sin almacenamiento en servidores, todo en tu navegador.',
    'tgl.seo.use.heading': 'Donde Usar Tu Enlace de Telegram',
    'tgl.seo.use.text': 'Los enlaces de Telegram son muy versatiles. Ponlos en tu bio de Instagram — es uno de los lugares mas comunes. Agrega a la pagina de contacto de tu sitio web. Incluyelos en firmas de correo. Imprime QR en tarjetas, menus, flyers. Usalos en bots de Telegram para que usuarios inicien con un comando especifico. Las posibilidades son infinitas.',
    'tgl.seo.faq.heading': 'Preguntas Frecuentes',
    'tgl.seo.faq.q1': 'Es gratis crear un enlace de Telegram?',
    'tgl.seo.faq.a1': 'Si, completamente gratis. OPN Chat genera enlaces t.me sin costo, sin limites, sin registro y sin anuncios. Los enlaces funcionan para siempre — estan basados en el protocolo oficial de Telegram.',
    'tgl.seo.faq.q2': 'Que es el mensaje de inicio?',
    'tgl.seo.faq.a2': 'El mensaje de inicio es un texto predeterminado que aparece cuando alguien abre tu enlace de Telegram. Facilita que las personas inicien una conversacion. Por ejemplo: "Hola, quiero saber mas sobre tus servicios." Es especialmente util para bots de Telegram.',
    'tgl.seo.faq.q3': 'Necesita la otra persona saber mi nombre de usuario?',
    'tgl.seo.faq.a3': 'No. Cuando alguien clickea tu enlace t.me, Telegram abre un chat con tu cuenta o bot sin necesidad de conocer tu nombre de usuario. El enlace funciona como una puerta directa para iniciar una conversacion.',
    'tgl.seo.faq.q4': 'Puedo cambiar el enlace despues?',
    'tgl.seo.faq.a4': 'La estructura del enlace t.me es fija (t.me/NOMBREDEUSUARIO). Si cambias tu nombre de usuario, debes generar un nuevo enlace. El mensaje de inicio se puede cambiar generando un enlace con un mensaje diferente.',
    'tgl.seo.faq.q5': 'Funciona para bots y canales tambien?',
    'tgl.seo.faq.a5': 'Si! Los enlaces t.me funcionan para cuentas personales, bots y canales. Para bots, el parametro ?start= es especialmente poderoso — permite que los usuarios inicien tu bot con un comando especifico, ideal para onboarding y atencion al cliente.',
