    'wc.meta.title': 'Contador de Palabras y Caracteres — Gratis y Privado | OPN Chat',
    'wc.meta.description': 'Cuenta palabras, caracteres, oraciones y tiempo de lectura al instante. Analiza densidad de palabras clave para SEO. 100% privado — tu texto nunca sale de tu navegador. Gratis, sin registro.',
    'wc.meta.keywords': 'contador de palabras, contador de caracteres, contar palabras, analizador de texto, tiempo de lectura, densidad de palabras clave, herramienta SEO, contador gratuito, contador online',
