    'wc.copied': '¡Copiado!',
    'wc.features.heading': '¿Por Qué Usar Nuestro Contador?',
    'wc.features.private.title': '100% Privado',
    'wc.features.private.desc': 'Tu texto se procesa completamente en tu navegador. Nada se envía a ningún servidor. Ideal para escritores y estudiantes que valoran su privacidad.',
    'wc.features.instant.title': 'Análisis Instantáneo',
    'wc.features.instant.desc': 'Los resultados se actualizan mientras escribes. Sin botones, sin esperas. Palabras, caracteres y tiempo de lectura aparecen en tiempo real.',
    'wc.features.seo.title': 'Densidad SEO',
    'wc.features.seo.desc': 'Ve las 5 palabras más frecuentes y su porcentaje de densidad. Esencial para profesionales de SEO que optimizan meta tags, titulares y contenido.',
    'wc.features.everyday.title': 'Utilidad Diaria',
    'wc.features.everyday.desc': 'Verifica límites de palabras en ensayos, caracteres en Twitter/X, longitud en Instagram, o tiempo de lectura de blogs. Una herramienta para todas tus necesidades.',
    'wc.faq.heading': 'Preguntas Frecuentes',
    'wc.faq.q1': '¿Cómo funciona el contador de palabras?',
    'wc.faq.a1': 'El contador divide tu texto por espacios y puntuación para contar palabras. Los caracteres se cuentan directamente. Las oraciones se detectan por punto, signo de interrogación y exclamación. Los párrafos se separan por saltos de línea.',
    'wc.faq.q2': '¿Cómo se calcula el tiempo de lectura?',
    'wc.faq.a2': 'El tiempo de lectura se basa en el estándar de 200 palabras por minuto. Por ejemplo, un artículo de 1000 palabras toma约5 minutos. Es la misma métrica usada por Medium y otras plataformas.',
    'wc.faq.q3': '¿Qué es la densidad de palabras clave?',
    'wc.faq.a3': 'La densidad muestra cuán frecuente aparece cada palabra respecto al total. Si "marketing" aparece 10 veces en 500 palabras, su densidad es 2%. Los profesionales de SEO usan esto para optimizar contenido.',
    'wc.faq.q4': '¿Se almacena mi texto en algún lugar?',
    'wc.faq.a4': 'No. Tu texto se procesa completamente en tu navegador con JavaScript. Nunca se envía a nuestros servidores. Al cerrar la página, el texto desaparece. Seguro para manuscritos no publicados.',
    'wc.faq.q5': '¿Funciona con texto que no es en inglés?',
    'wc.faq.a5': '¡Sí! Funciona con cualquier idioma — español, árabe, chino, ruso y más. La lógica de conteo se adapta a diferentes sistemas de escritura.',
