    'fmt.seo.what.heading': '¿Qué es el formato de texto en WhatsApp?',
    'fmt.seo.what.text': 'WhatsApp admite cuatro estilos de formato: negrita, cursiva, tachado y monoespaciado. Cada estilo usa caracteres especiales alrededor del texto — asteriscos para negrita, guiones bajos para cursiva, virgulillas para tachado y triple comilla invertida para monoespaciado. El Formateador de OPN Chat lo hace fácil: selecciona el estilo, escribe tu mensaje, y la herramienta envuelve el texto con los caracteres correctos automáticamente.',
