    'fmt.seo.why.feature2.title': 'Vista previa en WhatsApp',
    'fmt.seo.why.feature2.desc': 'Ve exactamente cómo aparecerá tu mensaje formateado en WhatsApp antes de copiarlo.',
    'fmt.seo.why.feature3.title': '100% Privado',
    'fmt.seo.why.feature3.desc': 'Tu texto nunca sale de tu navegador. No se envía datos a ningún servidor.',
    'fmt.seo.why.feature4.title': 'Funciona en todo',
    'fmt.seo.why.feature4.desc': 'Usa el texto formateado en WhatsApp, WhatsApp Business, WhatsApp Web y WhatsApp Desktop.',
    'fmt.seo.how.heading': 'Cómo usarlo',
    'fmt.seo.how.text': 'Selecciona el estilo (negrita, cursiva, tachado o monoespaciado) haciendo clic en el botón correspondiente. Escribe tu mensaje. El texto formateado aparece con los marcadores correctos y una vista previa muestra cómo se verá. Haz clic en Copiar y pégalo directamente en WhatsApp.',
    'fmt.faq.heading': 'Preguntas frecuentes',
    'fmt.faq.q1': '¿Cómo formatear texto en WhatsApp manualmente?',
    'fmt.faq.a1': 'Envuelve tu texto con caracteres especiales: *negrita*, _cursiva_, ~tachado~, ```monoespaciado```. OPN Chat lo hace automáticamente.',
    'fmt.faq.q2': '¿Puedo combinar varios formatos?',
    'fmt.faq.a2': 'Sí. Puedes seleccionar varios botones a la vez. Por ejemplo, negrita + cursiva produce *_negrita cursiva_*.',
    'fmt.faq.q3': '¿Funciona en WhatsApp Business?',
    'fmt.faq.a3': 'Sí. Los códigos de formato funcionan igual en WhatsApp, WhatsApp Business, WhatsApp Web y WhatsApp Desktop.',
    'fmt.faq.q4': '¿OPN Chat Formateador es gratis?',
