    'hub.service.widget.desc': 'Genera un widget flotante de chat de WhatsApp para tu sitio web. Personaliza colores, posición y mensaje de bienvenida. Código gratis, sin registro.',
    'hub.service.widget.cta': 'Crear Widget',

