    // Emoji Picker / Keyboard
    'bc.emojipicker': 'Selector de Emojis',
    'ep.heading': 'Selector de Emojis y Teclado — Copiar Emojis para WhatsApp y Telegram',
    'ep.subheading': 'Busca, navega y copia emojis instantáneamente para WhatsApp, Telegram, Instagram y cualquier plataforma. Catálogo completo con categorías y búsqueda por palabras.',
    'ep.privacy.badge': '100% Privado — La navegación de emojis se ejecuta en tu navegador, no se envían datos',
    'ep.meta.title': 'Selector de Emojis y Teclado — Copiar Emojis para WhatsApp, Telegram y Redes Sociales | OPN Chat',
    'ep.meta.description': 'Selector de emojis y teclado gratuito para WhatsApp, Telegram, Instagram y redes sociales. Busca emojis por categoría o palabra clave, copia instantáneamente. 9 categorías, más de 500 emojis, sin registro, 100% privado.',
    'ep.meta.keywords': 'selector de emojis, teclado de emojis, buscar emojis, copiar emoji, emojis para whatsapp, emojis para telegram, catálogo de emojis, buscador de emojis, selector de emojis online, emojis gratis, emoji para whatsapp, emoji para telegram, opnchat',
    'ep.meta.og.title': 'Selector de Emojis y Teclado — Copiar Emojis Instantáneamente',
    'ep.meta.og.description': 'Busca y copia emojis para WhatsApp, Telegram y redes sociales. 9 categorías, búsqueda por palabras, copia instantánea. Gratis y privado.',
    'ep.meta.twitter.title': 'Selector de Emojis y Teclado — Buscar Emojis Gratis',
    'ep.meta.twitter.description': 'Encuentra y copia emojis para WhatsApp, Telegram, Instagram. 9 categorías, búsqueda por palabras. Gratis y privado.',
    'ep.search.placeholder': 'Buscar emojis (ej. corazón, gato, fuego)...',
    'ep.search.noResults': 'No se encontraron emojis. Intenta con otra palabra.',
    'ep.cat.smileys': 'Emoticonos',
    'ep.cat.people': 'Personas',
    'ep.cat.animals': 'Animales',
    'ep.cat.food': 'Comida',
    'ep.cat.activities': 'Actividades',
    'ep.cat.travel': 'Viajes',
    'ep.cat.objects': 'Objetos',
    'ep.cat.symbols': 'Símbolos',
    'ep.cat.flags': 'Banderas',
    'ep.recent.heading': 'Usados Recientemente',
    'ep.copied': '¡Copiado!',
    'ep.seo.what.heading': '¿Qué es un Selector de Emojis?',
    'ep.seo.what.text': 'Un Selector de Emojis (también llamado Teclado de Emojis) es una herramienta online gratuita que te permite buscar, navegar y copiar cualquier carácter emoji directamente a tu portapapeles. A diferencia del selector de emojis integrado en tu teléfono o computador, que está limitado a las aplicaciones que estás usando actualmente, el Selector de Emojis de OPN Chat funciona en cualquier navegador y en cualquier dispositivo. Simplemente encuentra el emoji que deseas navegando por categorías o escribiendo una palabra clave, haz clic en él, y se copia instantáneamente a tu portapapeles — listo para pegar en WhatsApp, Telegram, Instagram, Twitter/X, TikTok, correo electrónico o cualquier campo de texto. El catálogo incluye más de 500 emojis organizados en 9 categorías, cada una con búsqueda por nombre y palabra clave.',
    'ep.seo.why.heading': '¿Por qué Usar un Selector de Emojis Online?',
    'ep.seo.why.feature1.title': 'Buscar por Palabra Clave',
    'ep.seo.why.feature1.desc': 'Escribe "corazón", "gato" o "fuego" y encuentra el emoji perfecto instantáneamente. No necesitas desplazarte por cientos de emojis — la búsqueda filtra simultáneamente en todas las 9 categorías, mostrando cada emoji que coincide con tu consulta.',
    'ep.seo.why.feature2.title': 'Copiar y Pegar en cualquier Lugar',
    'ep.seo.why.feature2.desc': 'Un clic copia el emoji a tu portapapeles. Pégalo directamente en mensajes de WhatsApp, chats de Telegram, biografías y captions de Instagram, posts de Twitter/X, comentarios de TikTok o cualquier plataforma. Los emojis son caracteres Unicode estándar, así funcionan en todas las plataformas.',
    'ep.seo.why.feature3.title': '100% Privado',
    'ep.seo.why.feature3.desc': 'El Selector de Emojis de OPN Chat se ejecuta completamente en tu navegador. No se suben las selecciones de emojis, no se almacenan datos en ningún servidor, y no se usan cookies para rastreo. Tu historial de navegación de emojis se guarda localmente en tu navegador solo por conveniencia — puedes borrarlo cuando quieras.',
    'ep.seo.why.feature4.title': 'Funciona en cualquier Dispositivo',
    'ep.seo.why.feature4.desc': 'El selector de emojis funciona en teléfonos, tabletas y computadores. En el móvil, reemplaza el teclado de emojis integrado limitado con un catálogo con búsqueda. En el escritorio, te da acceso a emojis cuando tu teclado no tiene un selector de emojis incorporado. No requiere instalación de aplicación.',
    'ep.seo.how.heading': '¿Cómo Funciona el Selector de Emojis?',
    'ep.seo.how.text': 'Usar el Selector de Emojis de OPN Chat es simple. Navega los emojis haciendo clic en una de las 9 pestañas de categoría (Emoticonos, Personas, Animales, Comida, Actividades, Viajes, Objetos, Símbolos, Banderas), o escribe una palabra clave en el campo de búsqueda para encontrar emojis en todas las categorías. Cuando veas el emoji que quieres, haz clic en él — el emoji se copia instantáneamente a tu portapapeles y una breve notificación confirma la copia. Pégalo en cualquier aplicación o campo de texto. Tus emojis usados recientemente se guardan localmente en tu navegador para que puedas encontrarlos rápidamente la próxima vez.',
    'ep.seo.faq.heading': 'Preguntas Frecuentes',
    'ep.faq.q1': '¿Los emojis funcionan en WhatsApp y Telegram?',
    'ep.faq.a1': '¡Sí! Todos los emojis en este selector son caracteres Unicode estándar, que WhatsApp, Telegram, Instagram, Twitter/X, TikTok, Facebook, SMS, correo electrónico y prácticamente todas las plataformas soportan. Cuando copias un emoji de OPN Chat y lo pegas en WhatsApp o Telegram, aparece exactamente como se espera tanto en tu dispositivo como en el del destinatario.',
    'ep.faq.q2': '¿El selector de emojis es gratuito?',
    'ep.faq.a2': 'Completamente gratuito. Sin registro, sin niveles premium, sin anuncios, sin límites. Navega y copia tantos emojis como quieras — la herramienta está disponible para todos sin ninguna restricción. Todo el procesamiento ocurre en tu navegador sin interacción con el servidor.',
    'ep.faq.q3': '¿OPN Chat rastrea mis selecciones de emojis?',
    'ep.faq.a3': 'No. OPN Chat no sube, registra ni rastrea ninguna selección de emojis. Tus emojis usados recientemente se guardan solo en el localStorage de tu navegador por conveniencia, para que puedas acceder a ellos rápidamente. Puedes borrar este historial en cualquier momento limpiando los datos de tu navegador. No se envía ninguna información a nuestros servidores.',
    'ep.faq.q4': '¿Cuántos emojis están disponibles?',
    'ep.faq.a4': 'El Selector de Emojis de OPN Chat incluye más de 500 emojis en 9 categorías: Emoticonos y Emociones (60+), Personas y Cuerpo (70+), Animales y Naturaleza (70+), Comida y Bebida (80+), Actividades y Deportes (60+), Viajes y Lugares (80+), Objetos (100+), Símbolos (90+) y Banderas (80+). El catálogo cubre los emojis más usados para mensajería y redes sociales.',
    'ep.faq.q5': '¿Puedo buscar emojis por palabra clave?',
    'ep.faq.a5': '¡Sí! Escribe cualquier palabra clave en el campo de búsqueda — por ejemplo "corazón", "gato", "fuego", "feliz", "comida", "coche" — y el selector filtra todos los emojis en cada categoría que coincidan. Cada emoji tiene múltiples palabras clave asignadas, así incluso si no sabes el nombre exacto del emoji, una palabra relacionada lo encontrará.',
    'footer.emojipicker.link': 'Selector de Emojis',

    'hub.service.emojipicker.title': 'Selector de Emojis y Teclado',
    'hub.service.emojipicker.desc': 'Busca y copia emojis para WhatsApp, Telegram y redes sociales. 9 categorías, búsqueda por palabras, copia instantánea. Gratis y privado.',
    'hub.service.emojipicker.cta': 'Seleccionar Emojis',

