    'cv.faq.heading': 'Perguntas Frequentes',
    'cv.faq.q1': 'Quão precisas são as conversões?',
    'cv.faq.a1': 'Nossas conversões usam fórmulas matemáticas precisas com aritmética de ponto flutuante de alta precisão. Para uso diário (cozinha, viagens, DIY), a precisão é mais que suficiente. Mostramos até 8 dígitos significativos para trabalhos que exigem precisão.',
    'cv.faq.q2': 'Funciona offline?',
    'cv.faq.a2': 'Sim! Após o primeiro carregamento, o conversor funciona completamente offline porque todos os cálculos são executados em JavaScript no seu navegador. Nenhuma chamada ao servidor é feita durante a conversão. Isso o torna perfeito para viagens quando você não tem acesso à internet.',
    'cv.faq.q3': 'Quais categorias de unidades estão disponíveis?',
    'cv.faq.a3': 'Suportamos 7 categorias: Comprimento (mm, cm, m, km, in, ft, yd, mi, nmi), Peso (mg, g, kg, t, oz, lb, st), Temperatura (Celsius, Fahrenheit, Kelvin), Volume (mL, L, fl oz, xícara, pinta, quarto, galão, colher de sopa, colher de chá), Velocidade (m/s, km/h, mph, nós, ft/s), Área (cm2, m2, km2, hectares, ft2, acres, mi2) e Dados (Bytes, KB, MB, GB, TB, bits, Kbit, Mbit).',
    'cv.faq.q4': 'Meus dados são enviados a algum servidor?',
    'cv.faq.a4': 'Não. Todas as conversões são calculadas localmente no seu navegador usando JavaScript. Nenhum valor, seleção de unidade ou histórico de conversão é enviado aos nossos servidores ou terceiros. Seus cálculos são completamente privados.',
    'cv.faq.q5': 'Por que usar isso em vez do Google?',
    'cv.faq.a5': 'O Google requer conexão com a internet e rastreia suas pesquisas. Nosso conversor funciona offline, respeita sua privacidade sem rastreamento, e oferece uma interface dedicada com funções de troca, cópia e referência rápida que o Google não oferece. Além disso, nosso PWA pode ser instalado na tela inicial.',

