    'qr.meta.title': 'Gerador de Código QR Grátis — Sem Cadastro, Sem Marca d\'Água | OPN Chat',
    'qr.meta.description': 'Gere códigos QR para URLs, WiFi, vCard e texto. Grátis, sem cadastro, sem marca d\'água, sem expiração. Privacidade primeiro — tudo funciona no seu navegador.',
