    'wl.seo.what.heading': 'O Que É um Link de WhatsApp?',
    'wl.seo.what.text': 'Um link de WhatsApp (também chamado de link click-to-chat) usa o protocolo oficial wa.me para que qualquer pessoa possa iniciar uma conversa com você no WhatsApp em um clique — sem salvar seu número primeiro. Quando alguém clica no seu link, o WhatsApp abre com uma mensagem predefinida pronta para enviar. Funciona em qualquer dispositivo, navegador e lugar do mundo. Empresas colocam esses links em bios de Instagram, sites, assinaturas de e-mail, panfletos impressos e até em códigos QR em locais físicos. OPN Chat gera esses links gratuitamente, inteiramente no seu navegador — nada é armazenado em nenhum servidor.',
    'wl.seo.why.heading': 'Por Que Criar um Link de WhatsApp?',
    'wl.seo.why.feature1.title': 'Contato em Um Clique',
    'wl.seo.why.feature1.desc': 'Seus clientes ou contatos podem falar com você instantaneamente. Sem salvar números, sem procurar — apenas clique e converse.',
    'wl.seo.why.feature2.title': 'Mensagens Predefinidas',
    'wl.seo.why.feature2.desc': 'Adicione uma mensagem padrão para que as pessoas saibam exatamente o que dizer ao contatá-lo. Ideal para consultas comerciais e acompanhamento de pedidos.',
    'wl.seo.why.feature3.title': 'Código QR Incluído',
    'wl.seo.why.feature3.desc': 'Todo link vem com um código QR grátis. Imprima em cartões de visita, menus, fachadas — escaneie e converse instantaneamente.',
    'wl.seo.why.feature4.title': 'Funciona em Todo Lugar',
    'wl.seo.why.feature4.desc': 'Coloque seu link na bio do Instagram, Facebook, Twitter, assinatura de e-mail, site, catálogo do WhatsApp Business — onde as pessoas possam clicar.',
    'wl.seo.how.heading': 'Como Funciona',
    'wl.seo.how.text': 'Criar um link de WhatsApp com OPN Chat leva menos de um minuto. Digite seu número de telefone com código do país, opcionalmente escreva uma mensagem predefinida que os usuários verão ao abrir o chat, e clique em "Gerar". Você recebe um link wa.me como https://wa.me/15551234567?text=Olá que pode copiar, compartilhar e incorporar em um código QR. Sem cadastro, sem armazenamento em servidor, tudo acontece no seu navegador.',
    'wl.seo.use.heading': 'Onde Usar Seu Link de WhatsApp',
    'wl.seo.use.text': 'Os links de WhatsApp são incrivelmente versáteis. Coloque-os na bio do Instagram — é um dos lugares mais comuns. Adicione à página de contato do seu site para que visitantes enviem mensagens diretamente. Inclua em assinaturas de e-mail para acompanhamentos rápidos. Imprima códigos QR em cartões de visita, menus de restaurantes, panfletos de eventos ou embalagens de entrega. Incorpore em anúncios do Facebook para converter cliques em conversas. Use no catálogo do WhatsApp Business para consultas de produtos. As possibilidades são infinitas.',
    'wl.seo.faq.heading': 'Perguntas Frequentes',
    'wl.seo.faq.q1': 'É grátis criar um link de WhatsApp?',
    'wl.seo.faq.a1': 'Sim, completamente grátis. OPN Chat gera links wa.me sem custo, sem limites, sem cadastro e sem anúncios. Os links funcionam para sempre — são baseados no protocolo oficial do WhatsApp.',
    'wl.seo.faq.q2': 'O que é a mensagem predefinida?',
    'wl.seo.faq.a2': 'A mensagem predefinida é um texto padrão que aparece no campo de chat quando alguém abre seu link. Facilita que as pessoas iniciem uma conversa e ajuda você a saber de onde vieram. Por exemplo: "Olá, quero saber mais sobre seus serviços."',
    'wl.seo.faq.q3': 'A outra pessoa precisa ter meu número salvo?',
    'wl.seo.faq.a3': 'Não. Quando alguém clica no seu link wa.me, o WhatsApp abre um chat com seu número independentemente de ter salvo. Porém, se você tiver configurações de privacidade que restringem mensagens de contatos desconhecidos, podem precisar adicionar seu número primeiro.',
    'wl.seo.faq.q4': 'Posso alterar o link depois?',
    'wl.seo.faq.a4': 'A estrutura do link wa.me é fixa (wa.me/CODIGODOPAÍS+NÚMERO). Se você mudar seu número, precisa gerar um novo link. A mensagem predefinida pode ser alterada a qualquer momento gerando um novo link com mensagem diferente.',
    'wl.seo.faq.q5': 'Funciona no meu país?',
    'wl.seo.faq.a5': 'Sim, os links wa.me funcionam em todos os países onde o WhatsApp está disponível oficialmente. OPN Chat simplesmente gera o link — o chat real acontece pelo WhatsApp, usando seu protocolo oficial.',

