    'tgl.seo.why.feature4.desc': 'Coloque seu link na bio do Instagram, Facebook, Twitter, assinatura de e-mail, site — em qualquer lugar onde alguem possa clicar. Telegram esta disponivel globalmente.',
    'tgl.seo.how.heading': 'Como Funciona',
    'tgl.seo.how.text': 'Criar um link de Telegram com OPN Chat leva menos de um minuto. Insira seu nome de usuario do Telegram (sem o @), opcionalmente escreva uma mensagem de inicio, e clique em "Gerar." Voce recebe um link t.me como https://t.me/seu_negocio?start=Ola que pode copiar, compartilhar e converter em QR. Sem cadastro, sem servidores, tudo no seu navegador.',
    'tgl.seo.use.heading': 'Onde Usar Seu Link de Telegram',
    'tgl.seo.use.text': 'Links de Telegram sao extremamente versatil. Coloque-os na bio do Instagram — um dos lugares mais comuns. Adicione a pagina de contato do seu site. Inclua em assinaturas de e-mail. Imprima QR codes em cartoes, menus, flyers. Use para bots de Telegram para que usuarios iniciem com um comando especifico. As possibilidades sao infinitas.',
    'tgl.seo.faq.heading': 'Perguntas Frequentes',
    'tgl.seo.faq.q1': 'E gratis criar um link de Telegram?',
    'tgl.seo.faq.a1': 'Sim, completamente gratis. OPN Chat gera links t.me sem custo, sem limites, sem cadastro e sem anuncios. Os links funcionam para sempre — baseados no protocolo oficial do Telegram.',
    'tgl.seo.faq.q2': 'O que e a mensagem de inicio?',
    'tgl.seo.faq.a2': 'A mensagem de inicio e um texto padrao que aparece quando alguem abre seu link de Telegram. Facilita o inicio da conversacao. Por exemplo: "Ola, quero saber mais sobre seus servicos." Especialmente util para bots de Telegram.',
    'tgl.seo.faq.q3': 'A outra pessoa precisa saber meu nome de usuario?',
    'tgl.seo.faq.a3': 'Nao. Quando alguem clica no seu link t.me, o Telegram abre um chat com sua conta ou bot sem necessidade de conhecer seu nome. O link funciona como porta direta para iniciar conversa.',
