    'tgl.seo.faq.q5': 'Funciona para bots e canais tambem?',
    'tgl.seo.faq.a5': 'Sim! Links t.me funcionam para contas pessoais, bots e canais. Para bots, o parametro ?start= e especialmente poderoso — permite que usuarios iniciem seu bot com comando especifico, ideal para onboarding e suporte.',
