    'wc.features.instant.title': 'Análise Instantânea',
    'wc.features.instant.desc': 'Os resultados atualizam enquanto você digita. Sem botões, sem esperas. Palavras, caracteres e tempo de leitura em tempo real.',
    'wc.features.seo.title': 'Densidade SEO',
    'wc.features.seo.desc': 'Veja as 5 palavras mais frequentes e seu percentual de densidade. Essencial para profissionais de SEO otimizando meta tags e conteúdo.',
    'wc.features.everyday.title': 'Utilidade Diária',
    'wc.features.everyday.desc': 'Verifique limites de palavras em ensaios, caracteres no Twitter/X, tempo de leitura de blogs. Uma ferramenta para todas suas necessidades.',
    'wc.faq.heading': 'Perguntas Frequentes',
    'wc.faq.q1': 'Como funciona o contador de palavras?',
    'wc.faq.a1': 'O contador divide seu texto por espaços e pontuação para contar palavras. Caracteres são contados diretamente. Frases são detectadas por ponto final, interrogação e exclamação. Parágrafos são separados por quebras de linha.',
    'wc.faq.q2': 'Como o tempo de leitura é calculado?',
    'wc.faq.a2': 'O tempo de leitura baseia-se no padrão de 200 palavras por minuto. Por exemplo, um artigo de 1000 palavras leva cerca de 5 minutos. É a mesma métrica usada pelo Medium.',
    'wc.faq.q3': 'O que é densidade de palavras-chave?',
    'wc.faq.a3': 'Densidade mostra quão frequente cada palavra aparece em relação ao total. Se "marketing" aparece 10 vezes em 500 palavras, a densidade é 2%. Profissionais de SEO usam isso para otimizar conteúdo.',
    'wc.faq.q4': 'Meu texto é armazenado em algum lugar?',
    'wc.faq.a4': 'Não. Seu texto é processado completamente no navegador com JavaScript. Nunca é enviado a servidores. Ao fechar a página, o texto desaparece. Seguro para manuscritos não publicados.',
    'wc.faq.q5': 'Funciona com texto em outros idiomas?',
    'wc.faq.a5': 'Sim! Funciona com qualquer idioma — português, inglês, árabe, chinês e mais. A lógica de contagem se adapta a diferentes sistemas de escrita.',
