    'fmt.seo.what.heading': 'O que é formatação de texto no WhatsApp?',
    'fmt.seo.what.text': 'WhatsApp suporta quatro estilos de formatação: negrito, itálico, tachado e monospace. Cada estilo usa caracteres especiais envolvendo o texto — asteriscos para negrito, underscores para itálico, tildes para tachado e triple backticks para monospace. O Formatador do OPN Chat facilita: selecione o estilo, digite a mensagem, e a ferramenta envolve automaticamente.',
