    'fmt.seo.why.feature1.title': 'Formatação com um clique',
    'fmt.seo.why.feature1.desc': 'Não precisa lembrar os códigos. Clique e o texto é envolvido automaticamente.',
    'fmt.seo.why.feature2.title': 'Preview no WhatsApp',
    'fmt.seo.why.feature2.desc': 'Veja exatamente como a mensagem formatada aparecerá antes de copiar.',
    'fmt.seo.why.feature3.title': '100% Privado',
    'fmt.seo.why.feature3.desc': 'Seu texto nunca sai do navegador. Nenhum dado enviado a servidores.',
    'fmt.seo.why.feature4.title': 'Funciona em tudo',
    'fmt.seo.why.feature4.desc': 'Use texto formatado no WhatsApp, WhatsApp Business, WhatsApp Web e Desktop.',
    'fmt.seo.how.heading': 'Como usar',
    'fmt.seo.how.text': 'Selecione o estilo (negrito, itálico, tachado ou monospace) clicando no botão. Digite sua mensagem. O texto formatado aparece com os marcadores corretos e o preview mostra como ficará. Clique em Copiar e cole no WhatsApp.',
    'fmt.faq.heading': 'Perguntas frequentes',
    'fmt.faq.q1': 'Como formatar texto no WhatsApp manualmente?',
    'fmt.faq.a1': 'Envolva o texto com caracteres especiais: *negrito*, _itálico_, ~tachado~, ```monospace```. OPN Chat faz isso automaticamente.',
    'fmt.faq.q2': 'Posso combinar vários formatos?',
    'fmt.faq.a2': 'Sim! Selecione vários botões ao mesmo tempo. Negrito + itálico produz *_negrito itálico_*.',
    'fmt.faq.q3': 'Funciona no WhatsApp Business?',
    'fmt.faq.a3': 'Sim. Os códigos funcionam igual em WhatsApp, WhatsApp Business, Web e Desktop.',
    'fmt.faq.q4': 'OPN Chat Formatador é grátis?',
    'fmt.faq.a4': 'Completamente grátis. Sem taxas ocultas, sem planos premium, sem anúncios.',
    'fmt.faq.q5': 'O destinatário verá a formatação?',
    'fmt.faq.a5': 'Sim, se usar uma versão recente do WhatsApp. Versões antigas podem mostrar os marcadores.',
