    // WhatsApp Chat Widget Generator
    'cw.heading': 'Gerador de Widget de Chat do WhatsApp',
    'cw.subheading': 'Crie um widget flutuante de chat do WhatsApp para seu site — personalize cores, posição, mensagem de boas-vindas e obtenha o código HTML para incorporar.',
    'cw.privacy.badge': '100% Privado — Código gerado no seu navegador, sem dados enviados',
    'cw.meta.title': 'Gerador de Widget de Chat do WhatsApp — Código Grátis para seu Site | OPN Chat',
    'cw.meta.description': 'Gere um widget de chat do WhatsApp grátis para seu site. Personalize posição, cor, mensagem de boas-vindas e obtenha o código HTML instantaneamente. Sem registro, 100% privado, funciona em qualquer site.',
    'cw.meta.keywords': 'widget de chat whatsapp, gerador de widget whatsapp, botao whatsapp para site, widget de chat ao vivo whatsapp, embed whatsapp no site, widget whatsapp gratis, botao flutuante whatsapp, plugin whatsapp site, widget click to chat',
    'cw.meta.og.title': 'Gerador de Widget de Chat do WhatsApp — Código Grátis',
    'cw.meta.og.description': 'Gere um widget de chat do WhatsApp para seu site. Personalize cores, posição, mensagem de boas-vindas. Grátis, instantâneo, privado.',
    'cw.meta.twitter.title': 'Gerador de Widget do WhatsApp — Grátis',
    'cw.meta.twitter.description': 'Crie um widget de chat do WhatsApp para qualquer site. Grátis, instantâneo, sem registro.',
