    'cw.form.welcome.placeholder': 'Olá! Como podemos ajudar?',
    'cw.form.button.label': 'Texto do botão',
    'cw.form.button.placeholder': 'Chat no WhatsApp',
    'cw.form.generate': 'Gerar Código do Widget',
    'cw.result.title': 'Seu Código HTML do Widget',
    'cw.copy': 'Copiar Código',
    'cw.copied': 'Copiado!',
    'cw.preview.label': 'Previsualização do Widget',
    'cw.seo.what.heading': 'O Que É um Widget de Chat do WhatsApp?',
    'cw.seo.what.text': 'Um Widget de Chat do WhatsApp é um botão flutuante ou popup que aparece no seu site, permitindo que visitantes iniciem uma conversa do WhatsApp com você em um clique. Quando um visitante clica no widget, o WhatsApp abre com uma mensagem pré-preenchida pronta para enviar — sem necessidade de salvar seu número de telefone primeiro. O widget aparece como um pequeno botão circular no canto do seu site que se expande em um popup de chat com uma mensagem de boas-vindas. O Gerador de Widget do OPN Chat permite criar este widget gratuitamente, personalizar sua aparência e comportamento, e obter um snippet de código HTML pronto para usar que você pode incorporar em qualquer site.',
    'cw.seo.why.heading': 'Por Que Adicionar um Widget do WhatsApp ao Seu Site?',
    'cw.seo.why.feature1.title': 'Contato Instantâneo com Clientes',
    'cw.seo.why.feature1.desc': 'Visitantes podem contactar você com um clique. Sem número para salvar, sem formulário de contato — basta clicar e começar a conversar no WhatsApp.',
    'cw.seo.why.feature2.title': 'Totalmente Personalizável',
    'cw.seo.why.feature2.desc': 'Escolha a cor do widget, posição, mensagem de boas-vindas e texto do botão. Combine perfeitamente com sua marca. Cada detalhe é configurável.',
    'cw.seo.why.feature3.title': '100% Grátis e Privado',
    'cw.seo.why.feature3.desc': 'Sem taxas mensais, sem níveis premium, sem coleta de dados. O código do widget é gerado no seu navegador e funciona no seu site independentemente.',
    'cw.seo.why.feature4.title': 'Funciona em Qualquer Site',
    'cw.seo.why.feature4.desc': 'Copie o código HTML e cole no WordPress, Shopify, Wix, Squarespace, Blogger ou qualquer site personalizado. Sem plugins ou extensões necessárias.',
    'cw.seo.how.heading': 'Como Funciona',
    'cw.seo.how.text': 'Criar um widget de chat do WhatsApp com OPN Chat leva menos de um minuto. Digite seu número do WhatsApp com código do país, opcionalmente adicione uma mensagem pré-preenchida para visitantes, escolha a posição do widget (canto esquerdo ou direito), selecione uma cor que combine com sua marca, escreva uma mensagem de boas-vindas para o popup e defina o texto do botão. Clique em "Gerar Código do Widget" e você recebe um snippet HTML completo. Copie e cole no HTML do seu site antes da tag body final, e o widget aparece imediatamente. Sem registro, sem armazenamento em servidores.',
    'cw.seo.use.heading': 'Onde Usar Seu Widget do WhatsApp',
    'cw.seo.use.text': 'Widgets de chat do WhatsApp são perfeitos para qualquer site que deseja facilitar a comunicação com clientes. Lojas online no Shopify ou WooCommerce usam para consultas de produtos e suporte de pedidos. Negócios de serviços como dentistas, advogados e agentes imobiliários colocam em landing pages para que clientes potenciais possam perguntar instantaneamente. Restaurantes e cafés os incorporam para solicitações de reservas. Hotéis e agências de viagem usam para confirmações de reservas e consultas de clientes. Blogs WordPress e sites de portfólio os adicionam para engajamento de leitores. O widget funciona em todas as plataformas que permitem HTML personalizado.',
    'cw.faq.heading': 'Perguntas Frequentes',
    'cw.faq.q1': 'O widget do WhatsApp é gratuito?',
    'cw.faq.a1': 'Sim, completamente grátis. OPN Chat gera o código do widget sem custo, sem limites, sem registro e sem anúncios. O código funciona no seu site independentemente — não há dependências externas ou taxas mensais.',
    'cw.faq.q2': 'Preciso instalar um plugin?',
    'cw.faq.a2': 'Não. Basta copiar o snippet de código HTML e colar no seu site. Funciona no WordPress, Shopify, Wix, Squarespace, Blogger e qualquer site personalizado que permita edição HTML. Sem plugins, extensões ou configuração no servidor.',
    'cw.faq.q3': 'Posso personalizar a aparência do widget?',
    'cw.faq.a3': 'Sim. Você pode escolher a posição do widget (canto esquerdo ou direito), a cor do botão, o texto da mensagem de boas-vindas e a etiqueta do botão. Todas as personalizações são feitas no gerador e o código final reflete suas escolhas exatamente.',
    'cw.faq.q4': 'O widget funciona em dispositivos móveis?',
    'cw.faq.a4': 'Sim. Em dispositivos móveis, clicar no widget abre o app do WhatsApp diretamente. No desktop, abre WhatsApp Web. O widget se adapta automaticamente ao dispositivo do visitante para a melhor experiência.',
    'cw.faq.q5': 'O widget coleta algum dado?',
    'cw.faq.a5': 'Não. O código do widget gerado pelo OPN Chat é HTML, CSS e JavaScript puramente no lado do cliente. Não envia nenhum dado ao OPN Chat ou qualquer servidor externo. Quando um visitante clica, vai diretamente ao WhatsApp usando o protocolo oficial wa.me.',
    'cw.footer.tagline': 'opnchat.net — Gerador de Widget de Chat do WhatsApp. Sem dados em servidores. Tudo funciona no seu navegador.',
    'cw.footer.disclaimer': 'OPN Chat não é afiliado ao Meta ou WhatsApp.',
