    // Fancy Text Generator (PT)
    'bc.fancytext': 'Texto Fancy',
    'ft.heading': 'Gerador de Texto Fancy para WhatsApp e Redes Sociais',
    'ft.subheading': 'Transforme seu texto em fontes Unicode estilizadas — negrito, itálico, script, circular e mais. Copie e cole diretamente no WhatsApp, Telegram, Instagram ou qualquer plataforma.',
    'ft.privacy.badge': '100% Privado — A conversão é feita no seu navegador, nenhum dado enviado',
    'ft.meta.title': 'Gerador de Texto Fancy — Fontes Unicode Estilizadas para WhatsApp e Redes Sociais | OPN Chat',
    'ft.meta.description': 'Gerador gratuito de texto fancy para WhatsApp, Telegram, Instagram e redes sociais. Converta texto em negrito, itálico, script, circular, double-struck e mais estilos Unicode. Sem cadastro, 100% privado.',
    'ft.meta.keywords': 'gerador de texto fancy, texto estilizado, gerador de fontes unicode, texto fancy whatsapp, texto fancy instagram, gerador texto negrito, gerador texto itálico, texto circular, fonte script, texto cool, fonte fancy para whatsapp, conversor texto unicode, opnchat',
    'ft.meta.og.title': 'Gerador de Texto Fancy — Fontes Unicode Estilizadas',
    'ft.meta.og.description': 'Converta seu texto em fontes Unicode estilizadas para WhatsApp, Telegram e redes sociais. Grátis, instantâneo, privado.',
    'ft.meta.twitter.title': 'Gerador de Texto Fancy — Fontes Unicode Grátis',
    'ft.meta.twitter.description': 'Crie texto fancy para WhatsApp, Telegram, Instagram. Estilos negrito, itálico, script, circular. Grátis e privado.',
    'ft.form.input.label': 'Digite seu texto',
    'ft.form.input.placeholder': 'Escreva seu texto aqui...',
    'ft.form.input.hint': 'Apenas letras latinas (A-Z) são convertidas. Números, espaços e símbolos permanecem iguais.',
    'ft.copy': 'Copiar',
    'ft.copied': 'Copiado!',
    'ft.seo.what.heading': 'O Que É um Gerador de Texto Fancy?',
    'ft.seo.what.text': 'Um Gerador de Texto Fancy é uma ferramenta online gratuita que converte seu texto latino comum em estilos de caracteres Unicode visualmente distintos. Em vez de mudar a fonte — que só funciona onde você controla a exibição — substitui cada letra por um caractere Unicode especial que parece diferente mas ainda é texto válido. Isso significa que o texto fancy aparecerá corretamente no WhatsApp, Telegram, Instagram, Twitter/X, Facebook, TikTok e praticamente qualquer plataforma que aceite entrada de texto, porque Unicode é um padrão universal suportado por todos os dispositivos e navegadores modernos.',
    'ft.seo.why.heading': 'Por Que Usar Texto Fancy no WhatsApp e Redes Sociais?',
    'ft.seo.why.feature1.title': 'Destaque-se em Chats de Grupo',
    'ft.seo.why.feature1.desc': 'Em grupos de WhatsApp com centenas de mensagens, texto fancy torna suas mensagens notáveis instantaneamente. Estilos script negrito ou circular chamam atenção sem ser disruptivos, ajudando suas mensagens importantes a serem lidas.',
    'ft.seo.why.feature2.title': 'Expresse Sua Personalidade',
    'ft.seo.why.feature2.desc': 'Estilos de texto fancy permitem adicionar flair e individualidade às suas mensagens, bios e posts. Seja um visual fraktur sofisticado para um clan de gaming ou script elegante para uma nota pessoal, há um estilo que combina com sua vibe.',
    'ft.seo.why.feature3.title': 'Funciona em Tudo Instantaneamente',
    'ft.seo.why.feature3.desc': 'Como texto fancy usa caracteres Unicode reais, funciona no WhatsApp, Telegram, Instagram, Twitter/X, TikTok, SMS, email e qualquer campo de texto. Sem instalação de app, sem arquivos de fonte, sem problemas de compatibilidade. Copie, cole e envie.',
    'ft.seo.why.feature4.title': 'Risco de Privacidade Zero',
    'ft.seo.why.feature4.desc': 'O Gerador de Texto Fancy do OPN Chat funciona inteiramente no seu navegador. Nenhum texto é enviado, nenhum dado armazenado em qualquer servidor, e nenhum cookie usado para rastreamento. Seu texto permanece privado — sempre.',
    'ft.seo.how.heading': 'Como Funciona o Gerador de Texto Fancy?',
    'ft.seo.how.text': 'O gerador usa símbolos alfanuméricos matemáticos do Unicode — caracteres especiais projetados para notação matemática que parecem versões estilizadas de letras latinas comuns. Quando você digita "Olá", o gerador mapeia cada letra para seu equivalente negrito, script, circular e assim por diante. Como são caracteres Unicode reais, não mudanças de fonte, renderizam corretamente em qualquer dispositivo. OPN Chat suporta 13 estilos incluindo negrito, itálico, negrito itálico, script, script negrito, fraktur, fraktur negrito, double-struck, monospace, circular, squared, small caps e texto invertido.',
    'ft.seo.styles.heading': 'Quais Estilos de Texto Estão Disponíveis?',
    'ft.seo.styles.text': 'OPN Chat oferece 13 estilos Unicode distintos: Negrito para ênfase forte; Itálico para estilo sutil; Negrito Itálico ênfase combinada; Script cursiva elegante; Script Negrito cursiva pesada; Fraktur gótico/medieval; Fraktur Negrito gótico pesado; Double-Struck vazio/delineado; Monospace largura fixa técnico; Circulado dentro de círculos; Quadrado dentro de quadrados; Small Caps maiúsculas miniaturas; e Invertido texto invertido para efeitos divertidos.',
    'ft.seo.faq.heading': 'Perguntas Frequentes',
    'ft.faq.q1': 'Texto fancy funciona no WhatsApp?',
    'ft.faq.a1': 'Sim! Texto fancy usa caracteres Unicode reais, não fontes personalizadas. WhatsApp suporta Unicode totalmente, então negrito, script, circular e todos os outros estilos serão exibidos corretamente para remetente e destinatário, em qualquer dispositivo.',
    'ft.faq.q2': 'Posso usar texto fancy no Instagram e Telegram?',
    'ft.faq.a2': 'Absolutamente. Como texto fancy é Unicode padrão, funciona em bios do Instagram, captions, comentários, mensagens do Telegram, posts do Twitter/X, TikTok, Facebook, SMS, email e qualquer plataforma que aceite texto.',
    'ft.faq.q3': 'Por que números e símbolos permanecem iguais?',
    'ft.faq.a3': 'Símbolos alfanuméricos matemáticos do Unicode cobrem apenas letras latinas A-Z. Não há equivalentes especiais para dígitos 0-9, pontuação ou outros símbolos. Então números, espaços, vírgulas, pontos e emojis permanecem inalterados. Isso é uma limitação do padrão Unicode.',
    'ft.faq.q4': 'Texto fancy é grátis?',
    'ft.faq.a4': 'Sim, o Gerador de Texto Fancy do OPN Chat é completamente grátis sem cadastro, sem marcas de água e sem limites de uso. Você pode gerar tantos textos fancy quanto quiser e usá-los em qualquer lugar. Toda conversão acontece no seu navegador.',
    'ft.faq.q5': 'Meus amigos verão o texto fancy corretamente?',
    'ft.faq.a5': 'Em quase todos os casos, sim. Todos os smartphones modernos, computadores e navegadores suportam esses caracteres Unicode. A única exceção é se alguém usar um dispositivo muito antigo com suporte de fontes limitado, onde estilos exóticos podem aparecer como quadrados.',
    'footer.fancytext.link': 'Texto Fancy',

