    'ep.meta.description': 'Seletor de emojis e teclado gratuito para WhatsApp, Telegram, Instagram e redes sociais. Pesquise emojis por categoria ou palavra-chave, copie instantaneamente. 9 categorias, mais de 500 emojis, sem cadastro, 100% privado.',
    'ep.meta.keywords': 'seletor de emojis, teclado de emojis, buscar emojis, copiar emoji, emojis para whatsapp, emojis para telegram, catálogo de emojis, buscador de emojis, seletor de emojis online, emojis grátis, emoji para whatsapp, emoji para telegram, opnchat',
