    'ep.copied': 'Copiado!',
    'ep.seo.what.heading': 'O Que é um Seletor de Emojis?',
    'ep.seo.what.text': 'Um Seletor de Emojis (também chamado de Teclado de Emojis) é uma ferramenta online gratuita que permite pesquisar, navegar e copiar qualquer caractere emoji diretamente para sua área de transferência. Diferente do seletor de emojis embutido no seu celular ou computador, que é limitado aos apps que você está usando, o Seletor de Emojis do OPN Chat funciona em qualquer navegador e em qualquer dispositivo. Basta encontrar o emoji que você deseja navegando pelas categorias ou digitando uma palavra-chave, clicar nele, e ele é copiado instantaneamente para sua área de transferência — pronto para colar no WhatsApp, Telegram, Instagram, Twitter/X, TikTok, e-mail ou qualquer campo de texto. O catálogo inclui mais de 500 emojis organizados em 9 categorias, cada uma com busca por nome e palavra-chave.',
    'ep.seo.why.heading': 'Por Que Usar um Seletor de Emojis Online?',
    'ep.seo.why.feature1.title': 'Buscar por Palavra-Chave',
    'ep.seo.why.feature1.desc': 'Digite "coração", "gato" ou "fogo" e encontre o emoji perfeito instantaneamente. Não precisa rolar por centenas de emojis — a busca filtra simultaneamente em todas as 9 categorias, mostrando cada emoji que corresponde à sua consulta.',
    'ep.seo.why.feature2.title': 'Copiar e Colar em Qualquer Lugar',
    'ep.seo.why.feature2.desc': 'Um clique copia o emoji para sua área de transferência. Cole diretamente em mensagens do WhatsApp, chats do Telegram, biografias e captions do Instagram, posts do Twitter/X, comentários do TikTok ou qualquer plataforma. Os emojis são caracteres Unicode padrão, portanto funcionam em todas as plataformas.',
    'ep.seo.why.feature3.title': '100% Privado',
    'ep.seo.why.feature3.desc': 'O Seletor de Emojis do OPN Chat funciona inteiramente no seu navegador. Nenhuma seleção de emoji é enviada, nenhum dado é armazenado em servidor, e nenhum cookie é usado para rastreamento. Seu histórico de navegação de emojis é salvo localmente no navegador apenas por conveniência — você pode limpá-lo a qualquer momento.',
    'ep.seo.why.feature4.title': 'Funciona em Qualquer Dispositivo',
    'ep.seo.why.feature4.desc': 'O seletor de emojis funciona em celulares, tablets e computadores. No celular, substitui o teclado de emojis limitado com um catálogo pesquisável. No desktop, dá acesso a emojis quando seu teclado não tem um seletor embutido. Não precisa instalar app.',
    'ep.seo.how.heading': 'Como Funciona o Seletor de Emojis?',
    'ep.seo.how.text': 'Usar o Seletor de Emojis do OPN Chat é simples. Navegue pelos emojis clicando em uma das 9 abas de categoria (Emoticons, Pessoas, Animais, Comida, Atividades, Viagens, Objetos, Símbolos, Bandeiras), ou digite uma palavra-chave no campo de busca para encontrar emojis em todas as categorias. Quando você ver o emoji que quer, clique nele — o emoji é copiado instantaneamente para sua área de transferência e uma breve notificação confirma a cópia. Cole em qualquer app ou campo de texto. Seus emojis usados recentemente são salvos localmente no navegador para que você possa encontrá-los rapidamente na próxima vez.',
    'ep.seo.faq.heading': 'Perguntas Frequentes',
    'ep.faq.q1': 'Os emojis funcionam no WhatsApp e Telegram?',
    'ep.faq.a1': 'Sim! Todos os emojis neste seletor são caracteres Unicode padrão, que o WhatsApp, Telegram, Instagram, Twitter/X, TikTok, Facebook, SMS, e-mail e praticamente todas as plataformas suportam. Quando você copia um emoji do OPN Chat e cola no WhatsApp ou Telegram, ele aparece exatamente como deveria tanto no seu dispositivo quanto no do destinatário.',
    'ep.faq.q2': 'O seletor de emojis é gratuito?',
    'ep.faq.a2': 'Totalmente gratuito. Sem cadastro, sem níveis premium, sem anúncios, sem limites. Navegue e copie quantos emojis quiser — a ferramenta está disponível para todos sem nenhuma restrição. Todo o processamento acontece no seu navegador sem interação com servidor.',
    'ep.faq.q3': 'O OPN Chat rastreia minhas seleções de emojis?',
    'ep.faq.a3': 'Não. O OPN Chat não envia, registra ou rastreia nenhuma seleção de emojis. Seus emojis usados recentemente são salvos apenas no localStorage do seu navegador por conveniência, para que você possa acessá-los rapidamente. Você pode limpar este histórico a qualquer momento limpando os dados do navegador. Nenhuma informação é enviada aos nossos servidores.',
    'ep.faq.q4': 'Quantos emojis estão disponíveis?',
    'ep.faq.a4': 'O Seletor de Emojis do OPN Chat inclui mais de 500 emojis em 9 categorias: Emoticons e Emoções (60+), Pessoas e Corpo (70+), Animais e Natureza (70+), Comida e Bebida (80+), Atividades e Esportes (60+), Viagens e Lugares (80+), Objetos (100+), Símbolos (90+) e Bandeiras (80+). O catálogo cobre os emojis mais usados para mensagens e redes sociais.',
    'ep.faq.q5': 'Posso buscar emojis por palavra-chave?',
    'ep.faq.a5': 'Sim! Digite qualquer palavra-chave no campo de busca — por exemplo "coração", "gato", "fogo", "feliz", "comida", "carro" — e o seletor filtra todos os emojis em cada categoria que correspondem. Cada emoji tem várias palavras-chave atribuídas, então mesmo se você não sabe o nome exato do emoji, uma palavra relacionada vai encontrá-lo.',
    'footer.emojipicker.link': 'Seletor de Emojis',

