    'cv.features.instant.desc': 'Hasil muncul saat Anda mengetik. Tanpa memuat, tanpa menunggu. Mendukung lebih dari 50 pasang satuan di 7 kategori — dari kebutuhan sehari-hari seperti cm ke inci hingga satuan khusus seperti mil laut.',
    'cv.features.private.title': '100% Privat & Offline',
    'cv.features.private.desc': 'Semua perhitungan terjadi di peramban Anda. Tidak ada data yang dikirim ke server mana pun. Berfungsi offline setelah pemuatan pertama — sempurna untuk bepergian saat tidak ada koneksi internet.',
    'cv.features.offline.title': 'Berfungsi di Mana Saja',
    'cv.features.offline.desc': 'Gunakan di ponsel, tablet, atau komputer Anda. Desain responsif menyesuaikan layar apa pun. Tanpa instalasi — cukup bookmark dan Anda siap mengonversi.',
    'cv.features.everyday.title': 'Kebutuhan Sehari-hari',
    'cv.features.everyday.desc': 'Konversi yang paling banyak dicari: cm ke inci, kg ke pon, km ke mil, Fahrenheit ke Celsius. Plus ukuran memasak, penyimpanan data, luas tanah, dan satuan kecepatan.',

    'cv.faq.heading': 'Pertanyaan yang Sering Diajukan',
    'cv.faq.q1': 'Seberapa akurat konversinya?',
    'cv.faq.a1': 'Konversi kami menggunakan rumus matematika yang tepat dengan aritmatika titik mengambang berpresisi tinggi. Untuk penggunaan sehari-hari (memasak, bepergian, DIY), akurasinya lebih dari cukup. Kami menampilkan hingga 8 digit signifikan untuk pekerjaan yang membutuhkan presisi.',
    'cv.faq.q2': 'Apakah ini berfungsi offline?',
    'cv.faq.a2': 'Ya! Setelah pemuatan pertama, konverter berfungsi sepenuhnya offline karena semua perhitungan berjalan dalam JavaScript di peramban Anda. Tidak ada panggilan server selama konversi. Ini menjadikannya sempurna untuk bepergian saat Anda tidak memiliki akses internet.',
    'cv.faq.q3': 'Kategori satuan apa saja yang tersedia?',
    'cv.faq.a3': 'Kami mendukung 7 kategori: Panjang (mm, cm, m, km, in, ft, yd, mi, nmi), Berat (mg, g, kg, t, oz, lb, st), Suhu (Celsius, Fahrenheit, Kelvin), Volume (mL, L, fl oz, cangkir, pint, quart, galon, sdm, sdt), Kecepatan (m/s, km/h, mph, knot, ft/s), Luas (cm2, m2, km2, hektar, ft2, acre, mi2) dan Data (Bytes, KB, MB, GB, TB, bit, Kbit, Mbit).',
    'cv.faq.q4': 'Apakah data saya dikirim ke server mana pun?',
    'cv.faq.a4': 'Tidak. Semua konversi dihitung secara lokal di peramban Anda menggunakan JavaScript. Tidak ada nilai, pemilihan satuan, atau riwayat konversi yang pernah dikirim ke server kami atau pihak ketiga. Perhitungan Anda sepenuhnya privat.',
    'cv.faq.q5': 'Mengapa menggunakan ini daripada Google?',
    'cv.faq.a5': 'Google memerlukan koneksi internet dan melacak pencarian Anda. Konverter kami berfungsi offline, menghormati privasi Anda tanpa pelacakan, dan menyediakan antarmuka khusus dengan fitur tukar, salin, dan referensi cepat yang tidak ditawarkan Google. Plus, PWA kami dapat dipasang di layar utama Anda.',

