    'np.meta.title': 'Notepad Online — Gratis & Privat | OPN Chat',
    'np.meta.description': 'Notepad gratis yang menyimpan catatan di browser Anda. Tanpa daftar, tanpa cloud, tanpa data dikirim ke server mana pun. Catatan Anda tetap privat di perangkat Anda.',
