    'np.features.heading': 'Mengapa Menggunakan OPN Notepad?',
    'np.features.local.title': '100% Penyimpanan Lokal',
    'np.features.local.desc': 'Catatan Anda disimpan di localStorage browser Anda. Tanpa cloud, tanpa server, tanpa akun. Data Anda tidak pernah keluar dari perangkat Anda.',
    'np.features.instant.title': 'Instan & Cepat',
    'np.features.instant.desc': 'Tanpa layar pemuatan, tanpa menunggu. Buka halaman dan mulai mengetik. Simpan otomatis memastikan Anda tidak pernah kehilangan pekerjaan.',
    'np.features.private.title': 'Sepenuhnya Privat',
    'np.features.private.desc': 'Tanpa pelacakan, tanpa analitik, tanpa pengumpulan data. Apa yang Anda ketik tetap antara Anda dan browser Anda. Titik.',
    'np.features.free.title': 'Gratis Selamanya',
    'np.features.free.desc': 'Tanpa paket premium, tanpa iklan, tanpa pendaftaran. Hanya notepad yang bersih dan sederhana yang berfungsi di perangkat apa pun.',

    'np.faq.heading': 'Pertanyaan Umum',
    'np.faq.q1': 'Di mana catatan saya disimpan?',
    'np.faq.a1': 'Catatan Anda disimpan di localStorage browser Anda. Ini berarti catatan tersebut hanya disimpan di perangkat Anda. Jika Anda menghapus data browser atau menggunakan browser yang berbeda, catatan Anda tidak akan tersedia di sana.',
    'np.faq.q2': 'Bisakah saya mengakses catatan dari perangkat lain?',
    'np.faq.a2': 'Tidak, karena catatan disimpan secara lokal di browser Anda, catatan tidak dapat diakses dari perangkat lain. Ini adalah fitur privasi — data Anda tidak pernah keluar dari perangkat Anda. Jika Anda perlu mentransfer catatan, gunakan fungsi Ekspor untuk menyimpannya sebagai file teks.',
    'np.faq.q3': 'Akankah saya kehilangan catatan jika menutup browser?',
    'np.faq.a3': 'Tidak, catatan Anda otomatis disimpan ke localStorage saat Anda mengetik. Catatan akan ada saat Anda kembali. Namun, jika Anda menghapus data lokal browser atau menggunakan mode penyamaran, catatan akan hilang.',
    'np.faq.q4': 'Apakah ada batasan berapa banyak catatan yang bisa saya buat?',
    'np.faq.a4': 'localStorage biasanya mengizinkan 5-10 MB per situs web, yang cukup untuk ribuan catatan teks. Jika Anda mencapai batas, Anda bisa mengekspor catatan lama dan menghapusnya untuk mengosongkan ruang.',
    'np.faq.q5': 'Bisakah saya mengekspor catatan saya?',
    'np.faq.a5': 'Ya! Klik tombol Ekspor untuk mengunduh semua catatan Anda sebagai file teks biasa. Anda juga dapat menyalin catatan individual ke papan klip.',

