    'pw.features.heading': 'Mengapa Menggunakan Generator Kami?',
    'pw.features.crypto.title': 'Aman Secara Kriptografis',
    'pw.features.crypto.desc': 'Menggunakan crypto.getRandomValues() — standar keacakan yang sama digunakan dalam enkripsi. Bukan Math.random().',
    'pw.features.local.title': '100% Pemrosesan Lokal',
    'pw.features.local.desc': 'Kata sandi Anda dibuat di browser Anda dan tidak pernah dikirim ke mana pun. Nol keterlibatan server.',
    'pw.features.custom.title': 'Sepenuhnya Dapat Disesuaikan',
    'pw.features.custom.desc': 'Kontrol panjang, jenis karakter, dan buat beberapa kata sandi sekaligus. Aturan Anda, kata sandi Anda.',
    'pw.features.free.title': 'Gratis & Tanpa Daftar',
    'pw.features.free.desc': 'Tanpa akun, tanpa batas, tanpa iklan. Cukup buka dan buat. Berfungsi di perangkat apa pun.',

    'pw.faq.heading': 'Pertanyaan yang Sering Diajukan',
    'pw.faq.q1': 'Apakah generator kata sandi ini benar-benar aman?',
    'pw.faq.a1': 'Ya. Kami menggunakan Web Crypto API (crypto.getRandomValues()), yang menyediakan angka acak secara kriptografis aman. Ini adalah standar yang sama digunakan untuk enkripsi dan sertifikat keamanan. Tidak seperti Math.random(), ini tidak dapat diprediksi.',
    'pw.faq.q2': 'Apakah kata sandi yang saya buat disimpan di mana pun?',
    'pw.faq.a2': 'Tidak. Semua kata sandi dibuat sepenuhnya di browser Anda menggunakan JavaScript. Tidak ada yang dikirim ke server kami atau layanan eksternal mana pun. Saat Anda menutup atau menyegarkan halaman, kata sandi yang dibuat akan hilang.',
    'pw.faq.q3': 'Seberapa panjang kata sandi saya harus?',
    'pw.faq.a3': 'Kami merekomendasikan minimal 16 karakter untuk keamanan yang kuat. Untuk akun keamanan tinggi (perbankan, email), gunakan 20+ karakter dengan semua jenis karakter diaktifkan. Setiap karakter tambahan secara eksponensial meningkatkan kemungkinan kombinasi.',
    'pw.faq.q4': 'Apa yang membuat kata sandi menjadi kuat?',
    'pw.faq.a4': 'Kata sandi yang kuat menggabungkan panjang (12+ karakter), keacakan (bukan kata kamus), dan keragaman (huruf besar, huruf kecil, angka, dan simbol). Meter kekuatan kami mengukur entropi — ukuran matematika dari ketidakdapatdiprediksian — untuk memberikan penilaian yang akurat.',
    'pw.faq.q5': 'Bisakah saya membuat beberapa kata sandi sekaligus?',
    'pw.faq.a5': 'Ya! Gunakan bagian "Buat Massal" untuk membuat hingga 10 kata sandi sekaligus. Anda dapat menyalin semuanya dengan satu klik.',
    'pw.faq.q6': 'Apa itu entropi dan mengapa penting?',
    'pw.faq.a6': 'Entropi mengukur ketidakdapatdiprediksian kata sandi dalam bit. Entropi yang lebih tinggi berarti lebih banyak kombinasi yang harus dicoba oleh penyerang. Kata sandi dengan 80+ bit entropi dianggap sangat kuat. Generator kami menampilkan entropi secara real time.',

