    'qr.features.heading': 'Mengapa Generator QR Ini Berbeda',
    'qr.features.noSignup.title': 'Tanpa Pendaftaran',
    'qr.features.noSignup.desc': 'Mulai membuat kode QR segera. Tanpa akun, tanpa email, tanpa hambatan — cukup buka dan buat.',
    'qr.features.noWatermark.title': 'Tanpa Watermark',
    'qr.features.noWatermark.desc': 'Kode QR Anda bersih dan profesional. Tidak seperti pesaing, kami tidak pernah menambahkan watermark pada kode QR gratis.',
    'qr.features.noExpiration.title': 'Tanpa Kedaluwarsa',
    'qr.features.noExpiration.desc': 'Kode QR statis berfungsi selamanya. Tanpa masa percobaan, tanpa tanggal kedaluwarsa, tanpa paywall kejutan setelah 14 hari.',
    'qr.features.privacyFirst.title': 'Privasi Utama',
    'qr.features.privacyFirst.desc': 'Data Anda tidak pernah meninggalkan peramban Anda. Tanpa pemrosesan server, tanpa pelacakan, tanpa pengumpulan data. Kami hanya menggunakan Cloudflare Web Analytics — tanpa cookies, tanpa PII.',
    'qr.faq.heading': 'Pertanyaan Umum',
    'qr.faq.q1': 'Apakah generator kode QR ini benar-benar gratis?',
    'qr.faq.a1': 'Ya, sepenuhnya gratis tanpa biaya tersembunyi. Tanpa pendaftaran, tanpa tingkat premium, tanpa iklan. Setiap fitur — termasuk ekspor SVG dan kustomisasi — tersedia tanpa biaya.',
    'qr.faq.q2': 'Apakah kode QR kedaluwarsa?',
    'qr.faq.a2': 'Tidak. Generator ini membuat kode QR statis yang berfungsi selamanya. Beberapa pesaing menawarkan kode QR "dinamis" yang kedaluwarsa setelah masa percobaan lalu menagih Anda — kami tidak melakukan itu.',
    'qr.faq.q3': 'Apakah data saya dikirim ke server mana pun?',
    'qr.faq.a3': 'Tidak. Kode QR dihasilkan sepenuhnya di peramban Anda menggunakan JavaScript. URL, kata sandi WiFi, kontak, dan teks Anda tidak pernah meninggalkan perangkat Anda. Kami tidak memiliki akses ke data Anda.',
    'qr.faq.q4': 'Jenis kode QR apa saja yang bisa saya buat?',
    'qr.faq.a4': 'Anda dapat menghasilkan kode QR untuk URL (tautan ke situs web), kredensial WiFi (agar tamu dapat terhubung dengan pemindaian), kartu kontak vCard (kartu nama digital), dan teks biasa. Jenis lainnya segera hadir.',
    'qr.faq.q5': 'Bisakah saya mengkustomisasi warna kode QR saya?',
    'qr.faq.a5': 'Ya! Anda dapat memilih warna utama dan latar belakang apa saja. Kami merekomendasikan menjaga kontras tinggi untuk pemindaian yang andal. Warna utama gelap di atas latar belakang terang bekerja paling baik.',
    'qr.faq.q6': 'Apa itu koreksi kesalahan dan level mana yang harus saya pilih?',
    'qr.faq.a6': 'Koreksi kesalahan memungkinkan kode QR dibaca meskipun sebagian rusak. Level L memulihkan 7% data, M 15%, Q 25%, dan H 30%. Level yang lebih tinggi membuat kode QR lebih padat. Untuk sebagian besar penggunaan, M adalah keseimbangan terbaik. Pilih H jika Anda berencana menambahkan logo.',

