    'wc.features.heading': 'Kenapa Menggunakan Penghitung Kami?',
    'wc.features.private.title': '100% Privat',
    'wc.features.private.desc': 'Teks Anda diproses sepenuhnya di browser. Tidak ada yang dikirim ke server. Ideal untuk penulis dan mahasiswa yang menghargai privasi.',
    'wc.features.instant.title': 'Analisis Instan',
    'wc.features.instant.desc': 'Hasil diperbarui saat Anda mengetik. Tanpa tombol, tanpa tunggu. Kata, karakter, dan waktu baca muncul secara real-time.',
    'wc.features.seo.title': 'Kepadatan SEO',
    'wc.features.seo.desc': 'Lihat 5 kata paling sering dan persentase kepadatannya. Penting untuk profesional SEO yang mengoptimalkan meta tag dan konten.',
    'wc.features.everyday.title': 'Kegunaan Harian',
    'wc.features.everyday.desc': 'Periksa batas kata esai, karakter Twitter/X, panjang caption Instagram, atau waktu baca blog. Satu alat untuk semua kebutuhan menulis.',
    'wc.faq.heading': 'FAQ',
    'wc.faq.q1': 'Bagaimana penghitung kata bekerja?',
    'wc.faq.a1': 'Penghitung membagi teks Anda berdasarkan spasi dan tanda baca untuk menghitung kata. Karakter dihitung langsung. Kalimat dideteksi oleh titik, tanda seru, dan tanda tanya. Paragraf dipisahkan oleh baris baru.',
    'wc.faq.q2': 'Bagaimana waktu baca dihitung?',
    'wc.faq.a2': 'Waktu baca berdasarkan standar 200 kata per menit. Misalnya, artikel 1000 kata membutuhkan sekitar 5 menit. Metrik yang sama digunakan Medium.',
    'wc.faq.q3': 'Apa itu kepadatan kata kunci?',
    'wc.faq.a3': 'Kepadatan menunjukkan seberapa sering kata muncul relatif terhadap total kata. Jika "marketing" muncul 10 kali dalam 500 kata, kepadatannya 2%. Profesional SEO menggunakannya untuk mengoptimalkan konten.',
    'wc.faq.q4': 'Apakah teks saya disimpan?',
    'wc.faq.a4': 'Tidak. Teks Anda diproses sepenuhnya di browser dengan JavaScript. Tidak pernah dikirim ke server. Saat Anda menutup halaman, teks hilang. Aman untuk naskah yang belum dipublikasikan.',
    'wc.faq.q5': 'Apakah bekerja untuk teks non-Inggris?',
    'wc.faq.a5': 'Ya! Bekerja dengan bahasa apa pun — Indonesia, Inggris, Arab, Mandarin, dan lainnya. Logika penghitungan menyesuaikan dengan sistem penulisan yang berbeda.',
