    'cw.preview.label': 'Pratinjau Widget',
    'cw.seo.what.heading': 'Apa Itu Widget Chat WhatsApp?',
    'cw.seo.what.text': 'Widget Chat WhatsApp adalah tombol melayang atau popup yang muncul di website Anda, memungkinkan pengunjung memulai percakapan WhatsApp dengan Anda dalam satu klik. Ketika pengunjung mengklik widget, WhatsApp terbuka dengan pesan terisi otomatis yang siap dikirim — tanpa perlu menyimpan nomor telepon Anda terlebih dahulu. Widget biasanya muncul sebagai tombol bulat kecil di sudut website yang berkembang menjadi popup chat dengan pesan sambutan. Generator Widget OPN Chat memungkinkan Anda membuat widget ini gratis, mengkustomisasi tampilan dan perilakunya, serta mendapatkan snippet kode HTML yang siap digunakan dan dapat disematkan di website atau platform mana pun.',
    'cw.seo.why.heading': 'Mengapa Menambahkan Widget WhatsApp ke Website Anda?',
    'cw.seo.why.feature1.title': 'Kontak Pelanggan Instan',
    'cw.seo.why.feature1.desc': 'Pengunjung bisa menghubungi Anda dengan satu klik. Tidak perlu menyimpan nomor, tidak perlu mengisi formulir — cukup klik dan mulai chat di WhatsApp.',
    'cw.seo.why.feature2.title': 'Sepenuhnya Kustomizable',
    'cw.seo.why.feature2.desc': 'Pilih warna widget, posisi, pesan sambutan, dan teks tombol. Sesuaikan dengan brand Anda sempurna. Setiap detail bisa dikonfigurasi.',
    'cw.seo.why.feature3.title': '100% Gratis & Privat',
    'cw.seo.why.feature3.desc': 'Tanpa biaya bulanan, tanpa tier premium, tanpa pengumpulan data. Kode widget dibuat sepenuhnya di browser Anda dan berjalan di website Anda secara mandiri.',
    'cw.seo.why.feature4.title': 'Berfungsi di Website Mana Pun',
    'cw.seo.why.feature4.desc': 'Salin kode HTML dan tempel ke WordPress, Shopify, Wix, Squarespace, Blogger, atau website kustom mana pun. Tanpa plugin atau ekstensi yang diperlukan.',
    'cw.seo.how.heading': 'Cara Kerja',
    'cw.seo.how.text': 'Membuat widget chat WhatsApp dengan OPN Chat kurang dari satu menit. Masukkan nomor WhatsApp Anda dengan kode negara, tambahkan pesan terisi otomatis untuk pengunjung, pilih posisi widget (sudut kiri atau kanan), pilih warna yang sesuai brand Anda, tulis pesan sambutan untuk popup, dan atur teks tombol. Klik "Generate Kode Widget" dan Anda mendapatkan snippet HTML lengkap. Salin dan tempel ke HTML website Anda sebelum tag body penutup, dan widget muncul di situs Anda langsung. Tanpa registrasi, tanpa penyimpanan server.',
    'cw.seo.use.heading': 'Di Mana Menggunakan Widget WhatsApp Anda',
    'cw.seo.use.text': 'Widget chat WhatsApp cocok untuk website mana pun yang ingin memudahkan komunikasi pelanggan. Toko online di Shopify atau WooCommerce menggunakan untuk pertanyaan produk dan dukungan pesanan. Bisnis layanan seperti dokter gigi, pengacara, dan agen properti menempatkannya di landing page agar calon klien bisa bertanya langsung. Restoran dan kafe menyematkan untuk permintaan reservasi. Hotel dan agen perjalanan menggunakannya untuk konfirmasi booking dan pertanyaan tamu. Blog WordPress dan situs portofolio menambahkannya untuk interaksi pembaca. Widget berfungsi di semua platform yang memperbolehkan HTML kustom.',
    'cw.faq.heading': 'Pertanyaan yang Sering Diajukan',
    'cw.faq.q1': 'Apakah widget WhatsApp gratis?',
    'cw.faq.a1': 'Ya, sepenuhnya gratis. OPN Chat menghasilkan kode widget tanpa biaya, tanpa batas, tanpa registrasi, dan tanpa iklan. Kode berjalan di website Anda secara mandiri — tidak ada dependensi eksternal atau biaya bulanan.',
    'cw.faq.q2': 'Apakah saya perlu menginstal plugin?',
    'cw.faq.a2': 'Tidak. Anda hanya menyalin snippet kode HTML dan menempelnya ke website Anda. Berfungsi di WordPress, Shopify, Wix, Squarespace, Blogger, dan website kustom mana pun yang memperbolehkan editing HTML. Tanpa plugin, ekstensi, atau setup server.',
    'cw.faq.q3': 'Bisakah saya mengkustomisasi tampilan widget?',
    'cw.faq.a3': 'Ya. Anda bisa memilih posisi widget (sudut kiri atau kanan), warna tombol, teks pesan sambutan, dan label tombol. Semua kustomisasi dilakukan di generator dan kode final mencerminkan pilihan Anda secara persis.',
    'cw.faq.q4': 'Apakah widget berfungsi di perangkat mobile?',
    'cw.faq.a4': 'Ya. Di perangkat mobile, mengklik widget membuka app WhatsApp langsung. Di desktop, membuka WhatsApp Web. Widget secara otomatis menyesuaikan dengan perangkat pengunjung untuk pengalaman terbaik.',
    'cw.faq.q5': 'Apakah widget mengumpulkan data?',
    'cw.faq.a5': 'Tidak. Kode widget yang dibuat oleh OPN Chat adalah HTML, CSS, dan JavaScript murni di sisi klien. Tidak mengirim data ke OPN Chat atau server eksternal mana pun. Ketika pengunjung mengklik, mereka langsung ke WhatsApp menggunakan protokol resmi wa.me.',
    'cw.footer.tagline': 'opnchat.net — Generator Widget Chat WhatsApp. Tanpa data di server. Semua berjalan di browser Anda.',
    'cw.footer.disclaimer': 'OPN Chat tidak berafiliasi dengan Meta atau WhatsApp.',
