    // Fancy Text Generator (ID)
    'bc.fancytext': 'Teks Fancy',
    'ft.heading': 'Generator Teks Fancy untuk WhatsApp & Media Sosial',
    'ft.subheading': 'Ubah teks Anda menjadi font Unicode stylish — bold, italic, script, circled, dan lainnya. Salin dan tempel langsung ke WhatsApp, Telegram, Instagram, atau platform apa pun.',
    'ft.privacy.badge': '100% Privat — Konversi teks berjalan di browser Anda, tidak ada data yang dikirim',
    'ft.meta.title': 'Generator Teks Fancy — Font Unicode Stylish untuk WhatsApp & Media Sosial | OPN Chat',
    'ft.meta.description': 'Generator teks fancy gratis untuk WhatsApp, Telegram, Instagram, dan media sosial. Konversi teks ke bold, italic, script, circled, double-struck, dan lebih banyak gaya Unicode. Tanpa registrasi, 100% privat.',
    'ft.meta.keywords': 'generator teks fancy, teks stylish, generator font unicode, teks fancy whatsapp, teks fancy instagram, generator teks bold, generator teks italic, teks circled, font script, teks keren, font fancy untuk whatsapp, konverter teks unicode, opnchat',
    'ft.meta.og.title': 'Generator Teks Fancy — Font Unicode Stylish',
    'ft.meta.og.description': 'Ubah teks Anda menjadi font Unicode stylish untuk WhatsApp, Telegram, dan media sosial. Gratis, instan, privat.',
    'ft.meta.twitter.title': 'Generator Teks Fancy — Font Unicode Gratis',
    'ft.meta.twitter.description': 'Buat teks fancy untuk WhatsApp, Telegram, Instagram. Gaya bold, italic, script, circled. Gratis & privat.',
    'ft.form.input.label': 'Masukkan teks Anda',
    'ft.form.input.placeholder': 'Ketik teks Anda di sini...',
    'ft.form.input.hint': 'Hanya huruf Latin (A-Z) yang dikonversi. Angka, spasi, dan simbol tetap sama.',
    'ft.copy': 'Salin',
    'ft.copied': 'Disalin!',
    'ft.seo.what.heading': 'Apa Itu Generator Teks Fancy?',
    'ft.seo.what.text': 'Generator Teks Fancy adalah alat online gratis yang mengkonversi teks Latin biasa Anda menjadi gaya karakter Unicode yang visualnya berbeda. Daripada mengubah font — yang hanya bisa dilakukan di tempat yang Anda kontrol tampilannya — alat ini mengganti setiap huruf dengan karakter Unicode khusus yang tampak berbeda tapi masih merupakan teks yang valid. Ini berarti teks fancy akan muncul dengan benar di WhatsApp, Telegram, Instagram, Twitter/X, Facebook, TikTok, dan hampir semua platform yang menerima input teks, karena Unicode adalah standar universal yang didukung semua perangkat dan browser modern.',
    'ft.seo.why.heading': 'Kenapa Menggunakan Teks Fancy di WhatsApp & Media Sosial?',
    'ft.seo.why.feature1.title': 'Menonjol di Chat Grup',
    'ft.seo.why.feature1.desc': 'Di grup WhatsApp yang sibuk dengan ratusan pesan, teks fancy membuat pesan Anda langsung terlihat. Gaya bold script atau circled menarik perhatian tanpa mengganggu, membantu pesan penting Anda dibaca.',
    'ft.seo.why.feature2.title': 'Ekspresikan Personalitas Anda',
    'ft.seo.why.feature2.desc': 'Gaya teks fancy memungkinkan Anda menambahkan gaya dan individualitas ke pesan, bio, dan postingan Anda. Entah gaya fraktur untuk clan gaming atau script elegan untuk catatan personal, ada gaya yang cocok dengan vibe Anda.',
    'ft.seo.why.feature3.title': 'Berfungsi di Semua Tempat Instan',
    'ft.seo.why.feature3.desc': 'Karena teks fancy menggunakan karakter Unicode asli, berfungsi di WhatsApp, Telegram, Instagram, Twitter/X, TikTok, SMS, email, dan bidang teks mana pun. Tanpa instalasi app, tanpa file font, tanpa masalah kompatibilitas. Salin, tempel, dan kirim.',
    'ft.seo.why.feature4.title': 'Risiko Privasi Nol',
    'ft.seo.why.feature4.desc': 'Generator Teks Fancy OPN Chat berjalan sepenuhnya di browser Anda. Tidak ada teks yang diunggah, tidak ada data yang disimpan di server mana pun, dan tidak ada cookie yang digunakan untuk tracking. Teks Anda tetap privat — selalu.',
    'ft.seo.how.heading': 'Bagaimana Generator Teks Fancy Bekerja?',
    'ft.seo.how.text': 'Generator menggunakan simbol alfanumerik matematis Unicode — karakter khusus yang dirancang untuk notasi matematis yang tampak seperti versi stylish dari huruf Latin biasa. Ketika Anda mengetik "Halo", generator memetakan setiap huruf ke versi bold, script, circled, dan seterusnya. Karena ini karakter Unicode asli, bukan perubahan font, tampilan benar di semua perangkat. OPN Chat mendukung 13 gaya termasuk bold, italic, bold italic, script, bold script, fraktur, bold fraktur, double-struck, monospace, circled, squared, small caps, dan teks terbalik.',
    'ft.seo.styles.heading': 'Gaya Teks Apa yang Tersedia?',
    'ft.seo.styles.text': 'OPN Chat menawarkan 13 gaya Unicode yang berbeda: Bold untuk penekanan kuat; Italic untuk gaya halus; Bold Italic penekanan gabungan; Script kursif elegan; Bold Script kursif tebal; Fraktur Gothic/medieval; Bold Fraktur Gothic tebal; Double-Struck kosong/outlined; Monospace fixed-width teknis; Circled dalam lingkaran; Squared dalam kotak; Small Caps huruf kapital mini; dan Upside Down teks terbalik untuk efek fun.',
    'ft.seo.faq.heading': 'Pertanyaan yang Sering Diajukan',
    'ft.faq.q1': 'Apakah teks fancy berfungsi di WhatsApp?',
    'ft.faq.a1': 'Ya! Teks fancy menggunakan karakter Unicode asli, bukan font kustom. WhatsApp mendukung Unicode sepenuhnya, sehingga bold, script, circled, dan semua gaya lainnya akan tampil dengan benar untuk pengirim dan penerima, di perangkat apa pun.',
    'ft.faq.q2': 'Bisa menggunakan teks fancy di Instagram dan Telegram?',
    'ft.faq.a2': 'Tentu saja. Karena teks fancy adalah Unicode standar, berfungsi di bio Instagram, caption, komentar, pesan Telegram, postingan Twitter/X, TikTok, Facebook, SMS, email, dan platform apa pun yang menerima teks.',
    'ft.faq.q3': 'Kenapa angka dan simbol tetap sama?',
    'ft.faq.a3': 'Simbol alfanumerik matematis Unicode hanya mencakup huruf Latin A-Z. Tidak ada equivalent khusus untuk digit 0-9, punctuation, atau simbol lain. Jadi angka, spasi, koma, titik, dan emoji tetap tidak berubah. Ini keterbatasan standar Unicode.',
    'ft.faq.q4': 'Apakah teks fancy gratis?',
    'ft.faq.a4': 'Ya, Generator Teks Fancy OPN Chat sepenuhnya gratis tanpa registrasi, tanpa watermark, dan tanpa batasan penggunaan. Anda bisa menghasilkan teks fancy sebanyak yang Anda mau dan menggunakan di mana saja. Semua konversi berlangsung di browser Anda.',
    'ft.faq.q5': 'Apakah teman saya akan melihat teks fancy dengan benar?',
    'ft.faq.a5': 'Dalam hampir semua kasus, ya. Semua smartphone modern, komputer, dan browser mendukung karakter Unicode ini. Pengecualian hanya jika seseorang menggunakan perangkat sangat lama dengan dukungan font terbatas, di mana beberapa gaya exotic mungkin muncul sebagai kotak.',
    'footer.fancytext.link': 'Teks Fancy',

