    'bc.emojipicker': 'Pemilih Emoji',
    'ep.heading': 'Pemilih Emoji & Keyboard — Salin Emoji untuk WhatsApp & Telegram',
    'ep.subheading': 'Cari, jelajahi, dan salin emoji secara instan untuk WhatsApp, Telegram, Instagram, dan platform apa pun. Katalog lengkap dengan kategori dan pencarian kata kunci.',
    'ep.privacy.badge': '100% Privat — Penjelajahan emoji berjalan di browser Anda, tidak ada data yang dikirim',
    'ep.meta.title': 'Pemilih Emoji & Keyboard — Salin Emoji untuk WhatsApp, Telegram & Media Sosial | OPN Chat',
    'ep.meta.description': 'Pemilih emoji dan keyboard gratis untuk WhatsApp, Telegram, Instagram, dan media sosial. Cari emoji berdasarkan kategori atau kata kunci, salin secara instan. 9 kategori, 500+ emoji, tanpa daftar, 100% privat.',
    'ep.meta.keywords': 'pemilih emoji, keyboard emoji, pencarian emoji, salin emoji, emoji whatsapp, emoji telegram, katalog emoji, pencari emoji, pemilih emoji online, emoji gratis, emoji untuk whatsapp, emoji untuk telegram, opnchat',
    'ep.meta.og.title': 'Pemilih Emoji & Keyboard — Salin Emoji Secara Instan',
    'ep.meta.og.description': 'Cari dan salin emoji untuk WhatsApp, Telegram, dan media sosial. 9 kategori, pencarian kata kunci, salin instan. Gratis & privat.',
    'ep.meta.twitter.title': 'Pemilih Emoji & Keyboard — Pencarian Emoji Gratis',
    'ep.meta.twitter.description': 'Temukan dan salin emoji untuk WhatsApp, Telegram, Instagram. 9 kategori, pencarian kata kunci. Gratis & privat.',
    'ep.search.placeholder': 'Cari emoji (cth. hati, kucing, api)...',
