    'ep.seo.what.heading': 'Apa Itu Pemilih Emoji?',
    'ep.seo.what.text': 'Pemilih Emoji (juga disebut Keyboard Emoji) adalah alat online gratis yang memungkinkan Anda mencari, menjelajahi, dan menyalin karakter emoji langsung ke clipboard Anda. Berbeda dengan pemilih emoji bawaan di ponsel atau komputer Anda, yang terbatas pada aplikasi yang sedang digunakan, Pemilih Emoji OPN Chat bekerja di browser mana pun dan di perangkat apa pun. Anda cukup menemukan emoji yang diinginkan dengan menjelajahi kategori atau mengetik kata kunci, klik emoji tersebut, dan langsung disalin ke clipboard — siap ditempelkan di WhatsApp, Telegram, Instagram, Twitter/X, TikTok, email, atau bidang teks apa pun. Katalog ini mencakup lebih dari 500 emoji yang terorganisir dalam 9 kategori, masing-masing dapat dicari berdasarkan nama dan kata kunci.',
    'ep.seo.why.heading': 'Mengapa Menggunakan Pemilih Emoji Online?',
    'ep.seo.why.feature1.title': 'Cari dengan Kata Kunci',
    'ep.seo.why.feature1.desc': 'Ketik "hati", "kucing", atau "api" dan temukan emoji yang sempurna secara instan. Tidak perlu men-scroll melalui ratusan emoji — pencarian memfilter di semua 9 kategori secara simultan, menampilkan setiap emoji yang cocok dengan pencarian Anda.',
    'ep.seo.why.feature2.title': 'Salin & Tempel di Mana Saja',
    'ep.seo.why.feature2.desc': 'Satu klik menyalin emoji ke clipboard Anda. Tempelkan langsung ke pesan WhatsApp, chat Telegram, bio dan caption Instagram, post Twitter/X, komentar TikTok, atau platform mana pun. Emoji adalah karakter Unicode standar, sehingga berfungsi di semua platform.',
    'ep.seo.why.feature3.title': '100% Privat',
    'ep.seo.why.feature3.desc': 'Pemilih Emoji OPN Chat berjalan sepenuhnya di browser Anda. Tidak ada seleksi emoji yang diunggah, tidak ada data yang disimpan di server mana pun, dan tidak ada cookie yang digunakan untuk pelacakan. Riwayat penjelajahan emoji Anda disimpan secara lokal di browser hanya untuk kemudahan — Anda dapat menghapusnya kapan saja.',
    'ep.seo.why.feature4.title': 'Bekerja di Perangkat Apa Pun',
    'ep.seo.why.feature4.desc': 'Pemilih emoji bekerja di ponsel, tablet, dan komputer. Di perangkat mobile, menggantikan keyboard emoji bawaan yang terbatas dengan katalog yang dapat dicari. Di desktop, memberikan akses emoji ketika keyboard Anda tidak memiliki pemilih emoji bawaan. Tidak perlu instalasi aplikasi.',
    'ep.seo.how.heading': 'Bagaimana Cara Kerja Pemilih Emoji?',
    'ep.seo.how.text': 'Menggunakan Pemilih Emoji OPN Chat sangat mudah. Jelajahi emoji dengan mengklik salah satu dari 9 tab kategori (Emotikon, Orang, Hewan, Makanan, Aktivitas, Perjalanan, Objek, Simbol, Bendera), atau ketik kata kunci di kolom pencarian untuk menemukan emoji di semua kategori. Ketika Anda melihat emoji yang diinginkan, klik — emoji langsung disalin ke clipboard dan notifikasi singkat mengonfirmasi penyalinan. Tempelkan di aplikasi atau bidang teks apa pun. Emoji yang baru digunakan disimpan secara lokal di browser Anda agar Anda dapat menemukannya lagi dengan cepat.',
    'ep.seo.faq.heading': 'Pertanyaan Umum',
    'ep.faq.q1': 'Apakah emoji berfungsi di WhatsApp dan Telegram?',
    'ep.faq.a1': 'Ya! Semua emoji di pemilih ini adalah karakter Unicode standar, yang didukung oleh WhatsApp, Telegram, Instagram, Twitter/X, TikTok, Facebook, SMS, email, dan hampir semua platform. Ketika Anda menyalin emoji dari OPN Chat dan menempelkannya di WhatsApp atau Telegram, emoji muncul persis seperti yang diharapkan baik di perangkat Anda maupun perangkat penerima.',
    'ep.faq.q2': 'Apakah pemilih emoji gratis?',
    'ep.faq.a2': 'Sepenuhnya gratis. Tanpa daftar, tanpa tier premium, tanpa iklan, tanpa batasan. Jelajahi dan salin emoji sebanyak yang Anda mau — alat ini tersedia untuk semua orang tanpa pembatasan. Semua proses berjalan di browser Anda tanpa interaksi server.',
    'ep.faq.q3': 'Apakah OPN Chat melacak seleksi emoji saya?',
    'ep.faq.a3': 'Tidak. OPN Chat tidak mengunggah, mencatat, atau melacak seleksi emoji apa pun. Emoji yang baru digunakan disimpan hanya di localStorage browser Anda untuk kemudahan, agar Anda dapat mengaksesnya lagi dengan cepat. Anda dapat menghapus riwayat ini kapan saja dengan menghapus data browser. Tidak ada informasi yang dikirim ke server kami.',
    'ep.faq.q4': 'Berapa banyak emoji yang tersedia?',
    'ep.faq.a4': 'Pemilih Emoji OPN Chat mencakup lebih dari 500 emoji dalam 9 kategori: Emotikon & Emosi (60+), Orang & Tubuh (70+), Hewan & Alam (70+), Makanan & Minuman (80+), Aktivitas & Olahraga (60+), Perjalanan & Tempat (80+), Objek (100+), Simbol (90+), dan Bendera (80+). Katalog mencakup emoji yang paling sering digunakan untuk pesan dan media sosial.',
    'ep.faq.q5': 'Apakah saya bisa mencari emoji dengan kata kunci?',
    'ep.faq.a5': 'Ya! Ketik kata kunci apa pun di kolom pencarian — misalnya "hati", "kucing", "api", "senang", "makanan", "mobil" — dan pemilih memfilter semua emoji di setiap kategori yang cocok. Setiap emoji memiliki beberapa kata kunci yang ditugaskan, sehingga meskipun Anda tidak tahu nama emoji yang tepat, kata terkait akan menemukannya.',
    'footer.emojipicker.link': 'Pemilih Emoji',

