    'seo.why.feature4.desc': 'Напишите сообщение перед открытием чата. Идеально для деловых запросов, быстрых знакомств или напоминаний.',
    'seo.cases.heading': 'Частые ситуации использования',
    'seo.cases.text': 'OPN Chat полезен в десятках повседневных ситуаций. Свяжитесь с курьером или доставкой, не добавляя их в контакты. Напишите продавцу на Авито, OLX или Яндекс.Маркет. Обратитесь в компанию или к поставщику услуг без сохранения номера. Отправьте быстрое сообщение человеку, которого вы только встретили на мероприятии. Свяжитесь с арендодателями, водителями такси или персоналом отеля во время путешествий — всё без засорения списка контактов.',
    'seo.direct.heading': 'Прямое сообщение в WhatsApp — умный способ',
    'seo.direct.text': 'Также известный как «WhatsApp Direct» или «Click to Chat», OPN Chat использует официальный протокол ссылок wa.me для открытия чата с любым номером. Это значит, ваше сообщение отправляется через собственную безопасную инфраструктуру WhatsApp. OPN Chat просто предоставляет удобный интерфейс — мы никогда не перехватываем, не читаем и не храним ваши сообщения. Это то же самое, что вручную вводить ссылку wa.me, только быстрее и проще.',
