    'seo.faq.a2': 'Да — если вы отправите сообщение, получатель увидит ваш номер WhatsApp как в обычном разговоре. OPN Chat просто открывает чат, он не делает ваш номер анонимным.',
    'seo.faq.q3': 'Нужно ли другому человеку сохранить мой номер?',
