    'disclaimer.lastUpdated': 'Последнее обновление: Июль 2026',
    'disclaimer.independence.heading': 'Независимое приложение',
    'disclaimer.independence.text': 'OPN Chat (opnchat.net) — независимое веб-приложение, не связанное с Meta Platforms, Inc., WhatsApp LLC, OpenChat DAO, OpenAI или любыми их дочерними компаниями. Официальный сайт WhatsApp: <a href="https://whatsapp.com" target="_blank" rel="noopener noreferrer">whatsapp.com</a>. Имена «WhatsApp», «OpenChat» — зарегистрированные товарные знаки их владельцев.',
    'disclaimer.purpose.heading': 'Назначение сервиса',
    'disclaimer.purpose.text': 'OPN Chat предоставляет удобный интерфейс для открытия разговоров в WhatsApp с использованием официального протокола wa.me. OPN Chat не перехватывает, не читает, не хранит и не изменяет сообщения, отправляемые через WhatsApp.',
    'disclaimer.privacy.heading': 'Приватность и данные',
    'disclaimer.privacy.text': 'OPN Chat не собирает, не хранит и не передаёт персональные данные на внешние серверы. Номера телефонов используются только для генерации ссылки wa.me и опционально сохраняются в localStorage.',
    'disclaimer.warranty.heading': 'Без гарантий',
