    // Privacy Policy
    'privacy.meta.title': 'Политика приватности — OPN Chat',
    'privacy.meta.description': 'Политика приватности OPN Chat. Узнайте, как мы защищаем ваши данные.',
    'privacy.heading': 'Политика приватности',
    'privacy.lastUpdated': 'Последнее обновление: Июль 2026',
    'privacy.intro.heading': 'Введение',
    'privacy.intro.text': 'В OPN Chat ваша приватность — наш главный приоритет. Мы создали OPN Chat с философией «приватность прежде всего»: собираем абсолютный минимум данных и полностью прозрачны.',
    'privacy.nodata.heading': 'Без сбора персональных данных',
    'privacy.nodata.text': 'OPN Chat не собирает, не хранит и не передаёт персональные данные на внешние серверы. У нас нет баз данных, аккаунтов и серверных логов.',
    'privacy.cloudflare.heading': 'Аналитика (Cloudflare Web Analytics)',
    'privacy.cloudflare.text': 'Мы используем Cloudflare Web Analytics для общих статистик посещений. Этот инструмент принципиально отличается от Google Analytics.',
    'privacy.cloudflare.nocookie.heading': 'Без cookies',
    'privacy.cloudflare.nocookie.text': 'Скрипт не устанавливает cookies. Нет постоянного идентификатора, нет отслеживания.',
    'privacy.cloudflare.nocross.heading': 'Без кросс-сайтового отслеживания',
    'privacy.cloudflare.nocross.text': 'Аналитика не отслеживает вас на других сайтах. Нет сторонних трекеров и обмена данными.',
    'privacy.cloudflare.aggregated.heading': 'Только агрегированные данные',
    'privacy.cloudflare.aggregated.text': 'Собираются только анонимизированные метрики — общие просмотры, регион, тип устройства.',
    'privacy.cloudflare.nopii.heading': 'Без сбора PII',
    'privacy.cloudflare.nopii.text': 'Cloudflare Web Analytics не собирает персонально идентифицируемую информацию.',
    'privacy.cloudflare.conclusion.text': 'Cloudflare Web Analytics не требует баннера согласия на cookies в большинстве юрисдикций.',
    'privacy.localstorage.heading': 'Локальное хранение',
    'privacy.localstorage.text': 'OPN Chat использует localStorage для сохранения последних номеров. Данные никогда не покидают ваше устройство.',
    'privacy.thirdparty.heading': 'Сторонние сервисы',
    'privacy.thirdparty.text': 'OPN Chat генерирует ссылки с использованием официальных протоколов WhatsApp (wa.me) и Telegram (t.me). Мы не используем других сторонних сервисов.',
    'privacy.children.heading': 'Приватность детей',
    'privacy.children.text': 'OPN Chat не собирает персональную информацию от детей младше 13 лет.',
    'privacy.rights.heading': 'Ваши права',
    'privacy.rights.text': 'По GDPR и CCPA вы имеете право доступа, исправления и удаления персональных данных. Поскольку мы не собираем данные, запросов не требуется. Вопросы: <a href="mailto:privacy@opnchat.net">privacy@opnchat.net</a>.',
    'privacy.changes.heading': 'Изменения политики',
    'privacy.changes.text': 'Мы можем обновлять эту Политику приватности в любое время. Дата последней редакции указана вверху страницы.',
    'privacy.back': 'Назад в OPN Chat',
