    'tgl.preview.label': 'Tak polzovateli uvidyat vashu ssylku',
    'tgl.seo.what.heading': 'Chto takoe ssylka Telegram?',
    'tgl.seo.what.text': 'Ssylka Telegram (t.me) ispolzuet oficialnyj protokol Telegram, chtoby lyuboj chelovek mog nachat dialog s vashim botom, kanalom ili lichnym akkauntom v odin klik. Kogda vy dobavlyaete parametr ?start=, polzovateli uvidyat predzapolnennoe soobschenie, gotovoe k otpravke. Eto rabotaet na lyubom ustrojstve, brauzere i v lyuboj strane. Biznesy razmeshchayut takie ssylki v bio Instagram, na sajtakh, v email-podpisakh, na flaerakh i dazhe v QR-kodakh v fizicheskikh tochekakh. OPN Chat generiruet eti ssylki besplatno, polnostyu v vashem brauzere — nichego ne khranitsya na serverakh.',
    'tgl.seo.why.heading': 'Pochemu stoit sozdat ssylku Telegram?',
    'tgl.seo.why.feature1.title': 'Kontakt v odin klik',
    'tgl.seo.why.feature1.desc': 'Klienty ili kontakty mogut svyazatsya s vam mgnovenno cherez Telegram. Ne nuzhno iskat ili dobavlyat kontakty — prosto klik i nachalo chata.',
    'tgl.seo.why.feature2.title': 'Startovoe soobschenie',
    'tgl.seo.why.feature2.desc': 'Dobavite startovoe soobschenie, chtoby lyudi srazu znali, chto napisat pri obrashchenii. Otlichno podkhodit dlya biznes-zaprosov i podderzhki klientov.',
    'tgl.seo.why.feature3.title': 'QR-kod vklyuchen',
    'tgl.seo.why.feature3.desc': 'Kazhdaya ssylka soprovozhdaetsya besplatnym QR-kodom. Raspechatajte na vizitkakh, menu, storefront — skanirovajte i chatajte mgnovenno.',
    'tgl.seo.why.feature4.title': 'Rabotaet vezde',
    'tgl.seo.why.feature4.desc': 'Razmeshchajte ssylku v bio Instagram, Facebook, Twitter, email-podpisi, sajte — gde ugodno. Telegram dostupen globalno na vsekh platformakh.',
    'tgl.seo.how.heading': 'Kak eto rabotaet',
    'tgl.seo.how.text': 'Sozdanie ssylki Telegram s OPN Chat zanimayet menshe minuty. Vvedite vash username Telegram (bez @), optionally napisite startovoe soobschenie i nazhmite "Sozdat". Vy poluchite ssylku t.me vida https://t.me/your_business?start=Zdravstvuyte, kotoruyu mozhno kopirovat, delitssya i vstroit v QR-kod. Bez registratsii, bez serverov, vsyo v brauzere.',
    'tgl.seo.use.heading': 'Gde ispolzovat ssylku Telegram',
    'tgl.seo.use.text': 'Ssylki Telegram neveroyatno universalny. Razmeshchajte v bio Instagram — odno iz samykh populyarnykh mest. Dobavite na stranitsu kontaktov sajta. Vklyuchite v email-podpisi. Raspechatajte QR na vizitkakh, menu, flaerakh. Ispolzuyte dlya Telegram-botov, chtoby polzovateli nachinali s opredelennoj komandy. Vozmozhnosti bezgranichny.',
    'tgl.seo.faq.heading': 'Chasto zadavaemye voprosy',
    'tgl.seo.faq.q1': 'Eto besplatno — sozdavat ssylku Telegram?',
    'tgl.seo.faq.a1': 'Da, polnostyu besplatno. OPN Chat generiruet ssylki t.me bez stoimosti, bez limitov, bez registratsii i bez reklamy. Ssylki rabotayut vechno — osnovany na oficialnom protokole Telegram.',
    'tgl.seo.faq.q2': 'Chto takoe startovoe soobschenie?',
    'tgl.seo.faq.a2': 'Startovoe soobschenie — eto tekst, kotoryj appearaet v pole vvoda pri otkrytii vashey ssylki. Uproshchaet nachalo dialoga. Naprimer: "Zdravstvuyte, khochu uznat podrobnee o vashikh uslugakh." Osobenno polezno dlya Telegram-botov.',
    'tgl.seo.faq.q3': 'Nuzhno li drugomu cheloveku znat moy username?',
    'tgl.seo.faq.a3': 'Net. Kogda kto-to klikaet po vashey ssylke t.me, Telegram otkryvaet chat s vashim akkauntom ili botom bez neobkhodimosti znat username. Ssylka rabotaet kak pryamoj shlyuz dlya nachala dialoga.',
    'tgl.seo.faq.q4': 'Mozhno li izmenit ssylku potom?',
    'tgl.seo.faq.a4': 'Struktura ssylki t.me fiksirovana (t.me/USERNAME). Esli vy izmenite username, nuzhno sozdat novuyu ssylku. Startovoe soobschenie mozhno menyat v lyuboj moment, generiruya ssylku s novym tekstom.',
    'tgl.seo.faq.q5': 'Rabotaet li eto dlya botov i kanalov?',
    'tgl.seo.faq.a5': 'Da! Ssylki t.me rabotayut dlya lichnykh akkauntov, botov i kanalov. Dlya botov parametr ?start= osobenno moshchnyj — pozvolyaet polzovatelyam zapustit bota s konkretnoj komandoj, idealno dlya onboardinga i podderzhki.',
