    'cw.seo.what.heading': 'Что такое виджет чата WhatsApp?',
    'cw.seo.what.text': 'Виджет чата WhatsApp — это плавающая кнопка или всплывающее окно на вашем сайте, позволяющее посетителям начать разговор в WhatsApp одним кликом. Когда посетитель нажимает на виджет, WhatsApp открывается с готовым предзаполненным сообщением — не нужно сначала сохранять ваш номер телефона. Виджет обычно выглядит как маленькая круглая кнопка в углу сайта, которая при нажатии раскрывается в чат-окно с приветственным сообщением. Генератор OPN Chat позволяет создать этот виджет бесплатно, настроить его внешний вид и поведение, и получить готовый фрагмент HTML-кода, который можно встроить на любой сайт.',
    'cw.seo.why.heading': 'Почему стоит добавить виджет WhatsApp на свой сайт?',
    'cw.seo.why.feature1.title': 'Мгновенная связь с клиентами',
    'cw.seo.why.feature1.desc': 'Посетители могут связаться с вами одним кликом. Не нужно сохранять номер, не нужно заполнять форму контактов — просто нажмите и начните чат в WhatsApp.',
    'cw.seo.why.feature2.title': 'Полная настройка',
    'cw.seo.why.feature2.desc': 'Выберите цвет виджета, позицию, приветственное сообщение и текст кнопки. Сделайте его идеально подходящим вашему бренду. Каждый деталь настраиваема.',
    'cw.seo.why.feature3.title': '100% бесплатно и приватно',
    'cw.seo.why.feature3.desc': 'Без ежемесячных платежей, без премиум-тарифов, без сбора данных. Код виджета полностью генерируется в вашем браузере и работает на сайте независимо.',
    'cw.seo.why.feature4.title': 'Работает на любом сайте',
    'cw.seo.why.feature4.desc': 'Скопируйте HTML-код и вставьте в WordPress, Shopify, Wix, Squarespace, Blogger или любой кастомный сайт. Не нужны плагины или расширения.',
    'cw.seo.how.heading': 'Как это работает',
    'cw.seo.how.text': 'Создание виджета чата WhatsApp с OPN Chat занимает меньше минуты. Введите номер WhatsApp с кодом страны, добавьте предзаполненное сообщение для посетителей, выберите позицию (левый или правый угол), укажите цвет кнопки, напишите приветственное сообщение для всплывающего окна и задайте текст кнопки. Нажмите «Сгенерировать код виджета» — получите полный HTML-фрагмент. Скопируйте и вставьте его в HTML вашего сайта перед закрывающим тегом body, и виджет появится мгновенно. Без регистрации, без хранения на серверах.',
    'cw.seo.use.heading': 'Где использовать виджет WhatsApp',
    'cw.seo.use.text': 'Виджеты чата WhatsApp идеально подходят для любого сайта, который хочет упростить общение с клиентами. Интернет-магазины на Shopify или WooCommerce используют их для вопросов о товарах и поддержки заказов. Сервисные бизнесы — стоматологии, юристы, риелторы — размещают на лендингах, чтобы клиенты могли задавать вопросы мгновенно. Рестораны и кафе встраивают для запросов бронирования. Отели и турагентства используют для подтверждения бронирований и вопросов гостей. Блоги на WordPress и портфолио-сайты добавляют для вовлечения читателей. Виджет работает на всех платформах, поддерживающих вставку HTML.',
    'cw.faq.heading': 'Часто задаваемые вопросы',
    'cw.faq.q1': 'Виджет WhatsApp бесплатный?',
    'cw.faq.a1': 'Да, полностью бесплатный. OPN Chat генерирует код виджета без платы, без лимитов, без регистрации и без рекламы. Код работает на вашем сайте независимо — нет внешних зависимостей или ежемесячных платежей.',
    'cw.faq.q2': 'Нужно ли устанавливать плагин?',
    'cw.faq.a2': 'Нет. Просто скопируйте фрагмент HTML-кода и вставьте его на свой сайт. Работает на WordPress, Shopify, Wix, Squarespace, Blogger и любом кастомном сайте с редактированием HTML. Не нужны плагины, расширения или серверные настройки.',
    'cw.faq.q3': 'Можно ли настроить внешний вид виджета?',
    'cw.faq.a3': 'Да. Можно выбрать позицию виджета (левый или правый угол), цвет кнопки, текст приветственного сообщения и надпись на кнопке. Все настройки делаются в генераторе, и итоговый код точно отражает ваши выборы.',
    'cw.faq.q4': 'Виджет работает на мобильных устройствах?',
    'cw.faq.a4': 'Да. На мобильных устройствах нажатие на виджет открывает приложение WhatsApp напрямую. На компьютере открывается WhatsApp Web. Виджет автоматически адаптируется к устройству посетителя для лучшего опыта.',
    'cw.faq.q5': 'Виджет собирает какие-нибудь данные?',
    'cw.faq.a5': 'Нет. Код виджета от OPN Chat — это чисто клиентский HTML, CSS и JavaScript. Он не отправляет данные на OPN Chat или сторонние серверы. Когда посетитель нажимает, он переходит напрямую в WhatsApp по официальному протоколу wa.me.',
    'cw.footer.tagline': 'opnchat.net — Генератор виджета чата WhatsApp. Нет данных на серверах. Всё работает в браузере.',
    'cw.footer.disclaimer': 'OPN Chat не связан с Meta или WhatsApp.',
