    'tz.faq.title': 'Часто задаваемые вопросы',
    'tz.faq.q1': 'Как работает конвертер часовых зон?',
    'tz.faq.a1': 'Выберите ваш базовый часовой пояс и увидите текущее время в 12 крупных городах мгновенно. Вы также можете ввести конкретное время, чтобы увидеть, какое оно будет в других городах.',
    'tz.faq.q2': 'Учитывается ли переход на летнее время?',
    'tz.faq.a2': 'Да. Конвертер использует встроенный Intl.DateTimeFormat вашего браузера, который автоматически обрабатывает переходы на летнее/зимнее время для каждой часовой зоны.',
    'tz.faq.q3': 'Можно ли добавить больше городов?',
    'tz.faq.a3': 'Да. Нажмите «Добавить город», чтобы добавить любой из 40+ мировых городов в таблицу сравнения. Вы также можете удалить ненужные города.',
    'tz.faq.q4': 'Отправляются ли мои данные на сервер?',
    'tz.faq.a4': 'Нет. Всё работает полностью в вашем браузере с использованием JavaScript Intl API. Никакие данные не отправляются на сервер.',
    'tz.faq.q5': 'Почему это полезно для WhatsApp и Telegram?',
    'tz.faq.a5': 'Если вы отправляете сообщения WhatsApp или Telegram международным контактам, знание их местного времени помогает избежать отправки сообщений в 3 часа ночи. Этот инструмент показывает подходящее временное окно для каждого города.',

    'tz.seo.title': 'Зачем нужен конвертер часовых зон?',
    'tz.seo.feature1.title': 'Мгновенное сравнение',
    'tz.seo.feature1.desc': 'Увидите время в 12+ городах одновременно. Без ручных расчётов и таблиц часовых зон.',
    'tz.seo.feature2.title': 'С учётом летнего времени',
    'tz.seo.feature2.desc': 'Автоматически учитывает переход на летнее время. Всегда точное, даже при смене сезонов.',
    'tz.seo.feature3.title': 'Гибкий поиск времени',
    'tz.seo.feature3.desc': 'Введите любое время в вашей зоне и мгновенно увидите соответствующее время в Дубае, Нью-Йорке, Мумбаи и других городах.',
