    'tgl.seo.what.text': 'Ein Telegram-Link (t.me-Link) nutzt das offizielle Telegram-Protokoll, damit jeder eine Konversation mit deinem Bot, Kanal oder persoenlichen Konto mit einem Klick starten kann. Mit dem ?start=-Parameter sehen Nutzer eine vorausgefuellte Nachricht, die sofort gesendet werden kann. Funktioniert auf jedem Gerät, Browser und weltweit. Unternehmen nutzen diese Links in Instagram-Bios, auf Websites, in E-Mail-Signaturen, auf Flyern und in QR-Codes. OPN Chat erstellt diese Links kostenlos, vollstaendig im Browser — keine Server-Datenspeicherung.',
    'tgl.seo.why.heading': 'Warum einen Telegram-Link erstellen?',
    'tgl.seo.why.feature1.title': 'Ein-Klick-Kontakt',
    'tgl.seo.why.feature1.desc': 'Kunden oder Kontakte erreichen dich sofort auf Telegram. Keine Suche, keine Kontaktanlage — einfach klicken und chatten.',
    'tgl.seo.why.feature2.title': 'Start-Nachricht',
    'tgl.seo.why.feature2.desc': 'Fuege eine Standard-Start-Nachricht hinzu, sodass Leute genau wissen, was sie sagen sollen. Ideal fuer Geschaeftsanfragen und Kundenbetreuung.',
    'tgl.seo.why.feature3.title': 'QR-Code inklusive',
    'tgl.seo.why.feature3.desc': 'Jeder Link kommt mit einem kostenlosen QR-Code. Drucke ihn auf Visitenkarten, Speisekarten, Schaufenster — scannen und sofort chatten.',
    'tgl.seo.why.feature4.title': 'Funktioniert ueberall',
    'tgl.seo.why.feature4.desc': 'Setze deinen Link in Instagram-Bio, Facebook, Twitter, E-Mail-Signatur, Website — ueberall wo jemand klicken kann. Telegram ist weltweit verfügbar.',
    'tgl.seo.how.heading': 'Wie es funktioniert',
    'tgl.seo.how.text': 'Einen Telegram-Link mit OPN Chat erstellen dauert weniger als eine Minute. Gib deinen Telegram-Benutzername (ohne @) ein, optional eine Start-Nachricht, und klicke auf "Erstellen." Du erhaeltst einen t.me-Link wie https://t.me/dein_geschaeft?start=Hallo zum Kopieren, Teilen und als QR-Code. Keine Registrierung, keine Server, alles im Browser.',
    'tgl.seo.use.heading': 'Wo deinen Telegram-Link nutzen',
    'tgl.seo.use.text': 'Telegram-Links sind extrem vielseitig. Im Instagram-Bio — einer der haeufigsten Orte. Auf der Kontaktseite deiner Website. In E-Mail-Signaturen. QR-Codes auf Visitenkarten, Flyern. Fuer Telegram-Bots, damit Nutzer mit einem bestimmten Befehl starten. Die Moeglichkeiten sind endlos.',
    'tgl.seo.faq.heading': 'Haeufig gestellte Fragen',
    'tgl.seo.faq.q1': 'Ist es kostenlos, einen Telegram-Link zu erstellen?',
    'tgl.seo.faq.a1': 'Ja, komplett kostenlos. OPN Chat erstellt t.me-Links ohne Kosten, Limits, Registrierung und Werbung. Die Links funktionieren dauerhaft — basierend auf dem offiziellen Telegram-Protokoll.',
    'tgl.seo.faq.q2': 'Was ist die Start-Nachricht?',
    'tgl.seo.faq.a2': 'Die Start-Nachricht ist ein Standardtext, der beim Öffnen des Telegram-Links erscheint. Erleichtert den Gesprächsstart. Beispiel: "Hallo, ich möchte mehr über Ihre Dienstleistungen wissen." Besonders nuetzlich fuer Telegram-Bots.',
    'tgl.seo.faq.q3': 'Muss die andere Person meinen Benutzernamen kennen?',
    'tgl.seo.faq.a3': 'Nein. Wenn jemand deinen t.me-Link klickt, öffnet Telegram einen Chat mit deinem Konto oder Bot ohne den Benutzernamen zu kennen. Der Link ist ein direkter Zugang zum Gespräch.',
    'tgl.seo.faq.q4': 'Kann ich den Link spaeter ändern?',
    'tgl.seo.faq.a4': 'Die Link-Struktur ist fest (t.me/BENUTZERNAME). Wenn du deinen Benutzernamen änderst, musst du einen neuen Link erstellen. Die Start-Nachricht kann jederzeit durch Neuerstellung mit anderem Text geändert werden.',
    'tgl.seo.faq.q5': 'Funktioniert das auch fuer Bots und Kanaele?',
    'tgl.seo.faq.a5': 'Ja! t.me-Links funktionieren fuer persoenliche Konten, Bots und Kanaele. Fuer Bots ist der ?start=-Parameter besonders powerful — Nutzer koennen den Bot mit einem bestimmten Befehl starten, ideal fuer Onboarding und Support.',
    'tgl.linktype.label': 'Link-Typ',
    'tgl.linktype.bot': 'Bot-Start-Nachricht',
    'tgl.linktype.personal': 'Persoenliche Chat-Nachricht',
    'tgl.linktype.bot.desc': 'Verwendet ?start= Parameter — startet automatisch eine Bot-Konversation',
    'tgl.linktype.personal.desc': 'Verwendet ?text= Parameter — fuellt eine Nachricht im Chat vor (Telegram 2024)',
    'tgl.open': 'In Telegram oeffnen',
