    'cw.heading': 'WhatsApp-Chat-Widget-Generator',
    'cw.subheading': 'Erstellen ein schwebendes WhatsApp-Chat-Widget für Ihre Website — Farben, Position, Willkommensnachricht anpassen und einbettbaren HTML-Code erhalten.',
    'cw.privacy.badge': '100% Privat — Widget-Code wird im Browser erstellt, keine Daten gesendet',
    'cw.meta.title': 'WhatsApp-Chat-Widget-Generator — Kostenloser Einbettungscode für Ihre Website | OPN Chat',
    'cw.meta.description': 'Erstellen Sie ein kostenloses WhatsApp-Chat-Widget für Ihre Website. Position, Farbe, Willkommensnachricht anpassen und sofort den HTML-Einbettungscode erhalten. Keine Anmeldung, 100% privat, funktioniert auf jeder Website.',
    'cw.meta.keywords': 'whatsapp chat widget, whatsapp widget generator, whatsapp button für website, whatsapp live chat widget, whatsapp auf website einbetten, kostenloses whatsapp widget, schwebender whatsapp button, whatsapp website plugin, click to chat widget',
