    'cw.preview.label': 'Widget-Vorschau',
    'cw.seo.what.heading': 'Was ist ein WhatsApp-Chat-Widget?',
    'cw.seo.what.text': 'Ein WhatsApp-Chat-Widget ist ein schwebender Button oder Popup, der auf Ihrer Website erscheint und Besuchern ermöglicht, eine WhatsApp-Konversation mit Ihnen mit einem Klick zu starten. Wenn ein Besucher auf das Widget klickt, öffnet sich WhatsApp mit einer vorausgefüllten Nachricht — ohne dass Ihre Telefonnummer zuerst gespeichert werden muss. Das Widget erscheint als kleiner kreisförmiger Button in der Ecke der Website, der sich zu einem Chat-Popup mit Willkommensnachricht erweitert. Der Widget-Generator von OPN Chat ermöglicht Ihnen, dieses Widget kostenlos zu erstellen, sein Erscheinungsbild und Verhalten anzupassen und einen fertigen HTML-Code-Schnipsel zu erhalten.',
    'cw.seo.why.heading': 'Warum ein WhatsApp-Widget auf Ihrer Website?',
    'cw.seo.why.feature1.title': 'Sofortiger Kundenkontakt',
    'cw.seo.why.feature1.desc': 'Besucher können Sie mit einem Klick erreichen. Keine Nummer speichern, kein Kontaktformular — einfach klicken und auf WhatsApp chatten.',
    'cw.seo.why.feature2.title': 'Vollständig anpassbar',
    'cw.seo.why.feature2.desc': 'Widget-Farbe, Position, Willkommensnachricht und Button-Text wählen. Perfekt zu Ihrer Marke passen. Jedes Detail ist konfigurierbar.',
    'cw.seo.why.feature3.title': '100% kostenlos & privat',
    'cw.seo.why.feature3.desc': 'Keine monatlichen Gebühren, keine Premium-Tarife, keine Datenerfassung. Der Widget-Code wird vollständig in Ihrem Browser generiert und läuft unabhängig auf Ihrer Website.',
    'cw.seo.why.feature4.title': 'Funktioniert auf jeder Website',
    'cw.seo.why.feature4.desc': 'HTML-Code kopieren und in WordPress, Shopify, Wix, Squarespace, Blogger oder jede custom Website einfügen. Keine Plugins oder Erweiterungen nötig.',
    'cw.seo.how.heading': 'Wie es funktioniert',
    'cw.seo.how.text': 'Ein WhatsApp-Chat-Widget mit OPN Chat erstellen dauert weniger als eine Minute. WhatsApp-Nummer mit Länderkürzel eingeben, optional eine vorausgefüllte Nachricht, Widget-Position (links oder rechts), Button-Farbe, Willkommensnachricht und Button-Text festlegen. «Widget-Code generieren» klicken und einen vollständigen HTML-Schnipsel erhalten. Kopieren und vor dem schließenden body-Tag in Ihre Website einfügen — das Widget erscheint sofort. Keine Anmeldung, kein Server-Storage.',
    'cw.seo.use.heading': 'Wo Sie Ihr WhatsApp-Widget einsetzen',
    'cw.seo.use.text': 'WhatsApp-Chat-Widgets sind ideal für jede Website, die die Kundenkommunikation erleichtern möchte. Online-Shops auf Shopify oder WooCommerce nutzen sie für Produktanfragen und Bestellsupport. Dienstleister wie Zahnärzte, Anwälte und Immobilienmakler platzieren sie auf Landingpages für sofortige Kundenfragen. Restaurants und Cafés betten sie für Reservierungsanfragen ein. Hotels und Reiseagenturen nutzen sie für Buchungsbestätigungen. WordPress-Blogs und Portfolio-Seiten fügen sie für Leserinteraktion hinzu. Das Widget funktioniert auf jeder Plattform mit HTML-Einbettung.',
    'cw.faq.heading': 'Häufig gestellte Fragen',
    'cw.faq.q1': 'Ist das WhatsApp-Widget kostenlos?',
    'cw.faq.a1': 'Ja, vollständig kostenlos. OPN Chat generiert den Widget-Code ohne Kosten, ohne Limits, ohne Anmeldung und ohne Werbung. Der Code läuft unabhängig auf Ihrer Website — keine externen Abhängigkeiten oder monatlichen Gebühren.',
    'cw.faq.q2': 'Muss ich ein Plugin installieren?',
    'cw.faq.a2': 'Nein. Kopieren Sie einfach den HTML-Code-Schnipsel und fügen ihn in Ihre Website ein. Funktioniert mit WordPress, Shopify, Wix, Squarespace, Blogger und jeder custom Website mit HTML-Editing. Keine Plugins, Erweiterungen oder Server-Setup nötig.',
    'cw.faq.q3': 'Kann ich das Widget-Erscheinungsbild anpassen?',
    'cw.faq.a3': 'Ja. Widget-Position (links oder rechts), Button-Farbe, Willkommensnachricht-Text und Button-Label wählen. Alle Anpassungen im Generator gemacht, der finale Code spiegelt Ihre Auswahl genau.',
    'cw.faq.q4': 'Funktioniert das Widget auf Mobilgeräten?',
    'cw.faq.a4': 'Ja. Auf Mobilgeräten öffnet ein Klick direkt die WhatsApp-App. Auf Desktop öffnet sich WhatsApp Web. Das Widget passt sich automatisch an das Gerät des Besuchers an.',
    'cw.faq.q5': 'Erfasst das Widget Daten?',
    'cw.faq.a5': 'Nein. Der Widget-Code von OPN Chat ist reines client-side HTML, CSS und JavaScript. Er sendet keine Daten an OPN Chat oder externe Server. Beim Klick geht der Besucher direkt zu WhatsApp über das offizielle wa.me-Protokoll.',
    'cw.footer.tagline': 'opnchat.net — WhatsApp-Chat-Widget-Generator. Keine Daten auf Servern. Alles läuft im Browser.',
    'cw.footer.disclaimer': 'OPN Chat ist nicht mit Meta oder WhatsApp verbunden.',
