    'ft.copied': 'Kopiert!',
    'ft.seo.what.heading': 'Was ist ein Fancy-Text-Generator?',
    'ft.seo.what.text': 'Ein Fancy-Text-Generator ist ein kostenloses Online-Tool, das Ihren regulären lateinischen Text in visuell unterschiedliche Unicode-Zeichenstile konvertiert. Anstatt die Schriftart zu ändern — was nur funktioniert, wo Sie die Darstellung kontrollieren — ersetzt er jeden Buchstaben durch ein spezielles Unicode-Zeichen, das anders aussieht, aber weiterhin gültiger Text ist. Das bedeutet, dass der Fancy-Text korrekt in WhatsApp, Telegram, Instagram, Twitter/X, Facebook, TikTok und nahezu jeder Plattform angezeigt wird, die Texteingabe akzeptiert, weil Unicode ein universeller Standard ist, der von allen modernen Geräten und Browsern unterstützt wird.',
    'ft.seo.why.heading': 'Warum Fancy-Text in WhatsApp & Social Media verwenden?',
    'ft.seo.why.feature1.title': 'In Gruppenchats auffallen',
    'ft.seo.why.feature1.desc': 'In vollen WhatsApp-Gruppen mit hunderten Nachrichten macht Fancy-Text Ihre Beiträge sofort bemerkbar. Bold Script oder Circled-Stile ziehen Aufmerksamkeit, ohne störend zu wirken, und helfen Ihren wichtigen Nachrichten, gelesen zu werden.',
    'ft.seo.why.feature2.title': 'Persönlichkeit ausdrücken',
    'ft.seo.why.feature2.desc': 'Fancy-Text-Stile ermöglichen es Ihnen, Ihren Nachrichten, Bios und Posts Flair und Individualität zu verleihen. Egal ob ein raffiniertes Fraktur-Look für einen Gaming-Clan oder ein elegantes Script für eine persönliche Notiz — es gibt einen Stil, der zu Ihrem Vibe passt.',
    'ft.seo.why.feature3.title': 'Funktioniert überall sofort',
    'ft.seo.why.feature3.desc': 'Da Fancy-Text echte Unicode-Zeichen verwendet, funktioniert es in WhatsApp, Telegram, Instagram, Twitter/X, TikTok, SMS, E-Mail und jedem Textfeld. Keine App-Installation, keine Schriftdateien, keine Kompatibilitätsprobleme. Kopieren, einfügen, senden.',
    'ft.seo.why.feature4.title': 'Kein Datenschutzrisiko',
    'ft.seo.why.feature4.desc': 'Der OPN Chat Fancy-Text-Generator läuft vollständig in Ihrem Browser. Kein Text wird übertragen, keine Daten auf Servern gespeichert, und keine Cookies für Tracking verwendet. Ihr Text bleibt privat — immer.',
    'ft.seo.how.heading': 'Wie funktioniert der Fancy-Text-Generator?',
    'ft.seo.how.text': 'Der Generator verwendet mathematische alphanumerische Unicode-Symbole — spezielle Zeichen für mathematische Notation, die wie stilisierte Versionen regulärer lateinischer Buchstaben aussehen. Wenn Sie "Hallo" eingeben, mappt der Generator jeden Buchstaben auf sein Bold-, Script-, Circled-Äquivalent und so weiter. Da es echte Unicode-Zeichen sind, keine Schriftänderungen, werden sie auf jedem Gerät korrekt angezeigt. OPN Chat unterstützt 13 Stile: Bold, Italic, Bold Italic, Script, Bold Script, Fraktur, Bold Fraktur, Double-Struck, Monospace, Circled, Squared, Small Caps und Upside Down.',
    'ft.seo.styles.heading': 'Welche Text-Stile sind verfügbar?',
    'ft.seo.styles.text': 'OPN Chat bietet 13 verschiedene Unicode-Stile: Bold für starke Hervorhebung; Italic für dezenten Stil; Bold Italic kombinierte Hervorhebung; Script elegante Kursiva; Bold Script schwere Kursiva; Fraktur gotisch/medieval; Bold Fraktur schwere Gotik; Double-Struck hohl/outlined; Monospace technisch mit festen Breiten; Circled in Kreisen; Squared in Quadraten; Small Caps miniaturisierte Großbuchstaben; und Upside Down invertierter Text für lustige Effekte.',
    'ft.seo.faq.heading': 'Häufig gestellte Fragen',
    'ft.faq.q1': 'Funktioniert Fancy-Text in WhatsApp?',
    'ft.faq.a1': 'Ja! Fancy-Text verwendet echte Unicode-Zeichen, keine benutzerdefinierten Schriften. WhatsApp unterstützt Unicode vollständig, sodass Bold, Script, Circled und alle anderen Stile sowohl für den Sender als auch den Empfänger auf jedem Gerät korrekt angezeigt werden.',
    'ft.faq.q2': 'Kann ich Fancy-Text in Instagram und Telegram verwenden?',
    'ft.faq.a2': 'Absolut. Da Fancy-Text Standard-Unicode ist, funktioniert es in Instagram-Bios, Captions, Kommentaren, Telegram-Nachrichten, Twitter/X-Posts, TikTok, Facebook, SMS, E-Mail und jeder Plattform, die Text akzeptiert.',
    'ft.faq.q3': 'Warum bleiben Zahlen und Symbole unverändert?',
    'ft.faq.a3': 'Mathematische alphanumerische Unicode-Symbole decken nur lateinische Buchstaben A-Z ab. Es gibt keine speziellen Äquivalente für Ziffern 0-9, Satzzeichen oder andere Symbole. Daher bleiben Zahlen, Leerzeichen, Kommas, Punkte und Emojis unverändert. Dies ist eine Einschränkung des Unicode-Standards.',
    'ft.faq.q4': 'Ist Fancy-Text kostenlos?',
    'ft.faq.a4': 'Ja, der OPN Chat Fancy-Text-Generator ist völlig kostenlos ohne Anmeldung, ohne Wasserzeichen und ohne Nutzungsbeschränkungen. Sie können beliebig viele Fancy-Texte generieren und überall verwenden. Die Konvertierung läuft vollständig in Ihrem Browser.',
    'ft.faq.q5': 'Sehen meine Freunde den Fancy-Text korrekt?',
    'ft.faq.a5': 'In fast allen Fällen ja. Alle modernen Smartphones, Computer und Browser unterstützen diese Unicode-Zeichen. Die einzige Ausnahme: wenn jemand ein sehr altes Gerät mit eingeschränkter Schriftunterstützung verwendet, könnten einige exotische Stile als Kästchen erscheinen.',
    'footer.fancytext.link': 'Fancy Text',

