    // Emoji Picker / Keyboard
    'bc.emojipicker': 'Emoji-Picker',
    'ep.heading': 'Emoji-Picker & Keyboard — Emojis kopieren für WhatsApp & Telegram',
    'ep.subheading': 'Suchen, browsen und kopieren Sie Emojis sofort für WhatsApp, Telegram, Instagram und jede Plattform. Vollständiger Katalog mit Kategorien und Schlüsselwort-Suche.',
    'ep.privacy.badge': '100% Privat — Emoji-Browsing läuft in Ihrem Browser, keine Datenübertragung',
    'ep.meta.title': 'Emoji-Picker & Keyboard — Emojis kopieren für WhatsApp, Telegram & Social Media | OPN Chat',
    'ep.meta.description': 'Kostenloser Emoji-Picker und Keyboard für WhatsApp, Telegram, Instagram und Social Media. Emojis nach Kategorie oder Schlüsselwort suchen, sofort kopieren. 9 Kategorien, 500+ Emojis, keine Anmeldung, 100% privat.',
    'ep.meta.keywords': 'emoji picker, emoji keyboard, emoji suche, emoji kopieren, whatsapp emoji, telegram emoji, emoji katalog, emoji finder, online emoji picker, kostenlose emojis, emoji für whatsapp, emoji für telegram, opnchat',
    'ep.meta.og.title': 'Emoji-Picker & Keyboard — Emojis sofort kopieren',
    'ep.meta.og.description': 'Suchen und kopieren Sie Emojis für WhatsApp, Telegram und Social Media. 9 Kategorien, Schlüsselwort-Suche, sofortiges Kopieren. Kostenlos & privat.',
    'ep.meta.twitter.title': 'Emoji-Picker & Keyboard — Kostenlose Emoji-Suche',
    'ep.meta.twitter.description': 'Finden und kopieren Sie Emojis für WhatsApp, Telegram, Instagram. 9 Kategorien, Schlüsselwort-Suche. Kostenlos & privat.',
    'ep.search.placeholder': 'Emojis suchen (z.B. Herz, Katze, Feuer)...',
    'ep.search.noResults': 'Keine Emojis gefunden. Versuchen Sie ein anderes Schlüsselwort.',
    'ep.cat.smileys': 'Smileys',
    'ep.cat.people': 'Personen',
