    'ep.cat.travel': 'Reisen',
    'ep.cat.objects': 'Objekte',
    'ep.cat.symbols': 'Symbole',
    'ep.cat.flags': 'Flaggen',
    'ep.recent.heading': 'Zuletzt verwendet',
    'ep.copied': 'Kopiert!',
    'ep.seo.what.heading': 'Was ist ein Emoji-Picker?',
    'ep.seo.what.text': 'Ein Emoji-Picker (auch Emoji-Keyboard genannt) ist ein kostenloses Online-Tool, mit dem Sie jedes Emoji direkt in Ihre Zwischenablage suchen, browsen und kopieren können. Anders als der integrierte Emoji-Picker auf Ihrem Smartphone oder Computer, der nur in den Apps funktioniert, die Sie gerade verwenden, funktioniert der OPN Chat Emoji-Picker in jedem Browser auf jedem Gerät. Finden Sie einfach das gewünschte Emoji durch Kategorien oder Eingabe eines Schlüsselworts, klicken Sie darauf, und es wird sofort in die Zwischenablage kopiert — bereit zum Einfügen in WhatsApp, Telegram, Instagram, Twitter/X, TikTok, E-Mail oder jedes Textfeld. Der Katalog enthält über 500 Emojis, organisiert in 9 Kategorien, jede durchsuchbar nach Name und Schlüsselwort.',
    'ep.seo.why.heading': 'Warum einen Online-Emoji-Picker verwenden?',
    'ep.seo.why.feature1.title': 'Schlüsselwort-Suche',
    'ep.seo.why.feature1.desc': 'Tippen Sie „Herz", „Katze" oder „Feuer" und finden Sie das perfekte Emoji sofort. Kein Scrollen durch hunderte Emojis — die Suche filtert gleichzeitig alle 9 Kategorien und zeigt jedes Emoji, das Ihrer Suche entspricht.',
    'ep.seo.why.feature2.title': 'Kopieren & Einfügen überall',
    'ep.seo.why.feature2.desc': 'Ein Klick kopiert das Emoji in die Zwischenablage. Fügen Sie es direkt in WhatsApp-Nachrichten, Telegram-Chats, Instagram-Bios und Captions, Twitter/X-Posts, TikTok-Kommentare oder jede Plattform ein. Emojis sind Standard-Unicode-Zeichen und funktionieren überall.',
    'ep.seo.why.feature3.title': '100% Privat',
    'ep.seo.why.feature3.desc': 'Der OPN Chat Emoji-Picker läuft vollständig in Ihrem Browser. Keine Emoji-Auswahl wird übertragen, keine Daten auf Servern gespeichert, keine Cookies für Tracking. Ihre Emoji-Browsing-Historie wird lokal im Browser nur für Convenience gespeichert — Sie können sie jederzeit löschen.',
    'ep.seo.why.feature4.title': 'Funktioniert auf jedem Gerät',
    'ep.seo.why.feature4.desc': 'Der Emoji-Picker funktioniert auf Smartphones, Tablets und Computern. Auf Mobilgeräten ersetzt er das limitierte integrierte Emoji-Keyboard durch einen durchsuchbaren Katalog. Auf dem Desktop bietet Emoji-Zugriff, wenn Ihr Keyboard keinen eingebauten Emoji-Picker hat. Keine App-Installation erforderlich.',
    'ep.seo.how.heading': 'Wie funktioniert der Emoji-Picker?',
    'ep.seo.how.text': 'Die Verwendung des OPN Chat Emoji-Pickers ist einfach. Browse Emojis durch Klicken auf eine der 9 Kategorie-Tabs (Smileys, Personen, Tiere, Essen, Aktivitäten, Reisen, Objekte, Symbole, Flaggen), oder tippen Sie ein Schlüsselwort ins Suchfeld, um Emojis in allen Kategorien zu finden. Wenn Sie das gewünschte Emoji sehen, klicken Sie — das Emoji wird sofort kopiert und eine kurze Benachrichtigung bestätigt den Kopiervorgang. Fügen Sie es in jede App oder Textfeld ein. Ihre zuletzt verwendeten Emojis werden lokal im Browser gespeichert, damit Sie sie schnell wiederfinden.',
    'ep.seo.faq.heading': 'Häufig gestellte Fragen',
    'ep.faq.q1': 'Funktionieren Emojis in WhatsApp und Telegram?',
    'ep.faq.a1': 'Ja! Alle Emojis in diesem Picker sind Standard-Unicode-Zeichen, die WhatsApp, Telegram, Instagram, Twitter/X, TikTok, Facebook, SMS, E-Mail und praktisch jede Plattform unterstützt. Wenn Sie ein Emoji aus OPN Chat kopieren und in WhatsApp oder Telegram einfügen, erscheint es exakt wie vorgesehen auf Ihrem Gerät und dem Gerät des Empfängers.',
    'ep.faq.q2': 'Ist der Emoji-Picker kostenlos?',
    'ep.faq.a2': 'Vollständig kostenlos. Keine Anmeldung, keine Premium-Tarife, keine Werbung, keine Limits. Browse und kopieren Sie so viele Emojis wie Sie möchten — das Tool ist für alle ohne Einschränkungen verfügbar. Alle Verarbeitung läuft in Ihrem Browser ohne Server-Interaktion.',
    'ep.faq.q3': 'Verfolgt OPN Chat meine Emoji-Auswahl?',
    'ep.faq.a3': 'Nein. OPN Chat überträgt, protokolliert oder verfolgt keine Emoji-Auswahl. Ihre zuletzt verwendeten Emojis werden nur im localStorage Ihres Browsers für Convenience gespeichert, damit Sie schnell darauf zugreifen können. Sie können diese Historie jederzeit durch Löschen der Browserdaten entfernen. Keine Informationen werden an unsere Server gesendet.',
    'ep.faq.q4': 'Wie viele Emojis sind verfügbar?',
    'ep.faq.a4': 'Der OPN Chat Emoji-Picker enthält über 500 Emojis in 9 Kategorien: Smileys & Emotionen (60+), Personen & Körper (70+), Tiere & Natur (70+), Essen & Trinken (80+), Aktivitäten & Sport (60+), Reisen & Orte (80+), Objekte (100+), Symbole (90+) und Flaggen (80+). Der Katalog deckt die am häufigsten verwendeten Emojis für Messaging und Social Media ab.',
    'ep.faq.q5': 'Kann ich Emojis nach Schlüsselwort suchen?',
    'ep.faq.a5': 'Ja! Tippen Sie beliebige Schlüsselwörter ins Suchfeld — z.B. „Herz", „Katze", „Feuer", „glücklich", „Essen", „Auto" — und der Picker filtert alle Emojis in jeder Kategorie, die passen. Jedem Emoji sind mehrere Schlüsselwörter zugewiesen, sodass auch ohne den exakten Namen ein verwandtes Wort das Emoji findet.',
    'footer.emojipicker.link': 'Emoji-Picker',

