    'tz.faq.q2': 'Berücksichtigt er die Sommerzeit?',
    'tz.faq.a2': 'Ja. Der Konverter verwendet den integrierten Intl.DateTimeFormat Ihres Browsers, der automatisch Sommerzeit-Übergänge für jede Zeitzone handled.',
    'tz.faq.q3': 'Kann ich weitere Städte hinzufügen?',
