    'tgl.share.label': 'Sharik rabitik',
    'tgl.preview.label': 'Hadha ma yarah al-mustakhdimun',
    'tgl.seo.what.heading': 'Ma hu rabit tilejgram?',
    'tgl.seo.what.text': 'Rabit tilejgram (t.me) yastakhdim al-burtukul al-rasm li tilejgram litamkin ay shakhs min bad muhadatha ma botik, qanatak aw hasabik al-shakhsi bi nqra wahida. An idafat muamil ?start=, yara al-mustakhdimun risala mubah maqblan jahiza li al-irsal. Yamal ala ay jihaz wa mutasaffih wa balad. Al-amal tada hadhi al-rabitat fi banar instghram, al-mawaqi, tawqiat al-barid, al-matbuat wa ramiz QR. OPN Chat yullid hadhi al-rabitat majanan, kuliyan fi mutasaffihik — la shay yukhzan ala khawadim.',
    'tgl.seo.why.heading': 'Limadha insha rabit tilejgram?',
    'tgl.seo.why.feature1.title': 'Tawasul bi nqra wahida',
    'tgl.seo.why.feature1.desc': 'Amilak aw jihat al-ittisal yimkinan al-wusul ilayk fawran ala tilejgram. Bila bahth, bila idafat — faqat nqra wa bad al-muhadatha.',
    'tgl.seo.why.feature2.title': 'Risalat al-bad',
    'tgl.seo.why.feature2.desc': 'Idif risalat bad iftiradiya liya rif al-nas ma da yaqulun an al-ittisal bik. Mithali li istifsarat al-amal wa khidmat al-amilin.',
    'tgl.seo.why.feature3.title': 'Ramiz QR mashmul',
    'tgl.seo.why.feature3.desc': 'Kul rabit yati ma ramiz QR majani. Ibtihu ala bitaqat al-amal, al-kutayib, al-matjar — amskh wa tawasul fawran.',
    'tgl.seo.why.feature4.title': 'Yamal fi kul makan',
    'tgl.seo.why.feature4.desc': 'Dda rabitik fi banar instghram, faysbuk, tuitr, tawqiat al-barid, al-mawqi — fi ay makan yimkin al-nqar alayh. Tilejgram mutah alaman.',
    'tgl.seo.how.heading': 'Kayf yamal',
    'tgl.seo.how.text': 'Insha rabit tilejgram ma OPN Chat yastaghriq akal min daqiqa. Udkhal ism al-mustakhdim (bila @), optionally idif risalat bad, wa anqar "Insha". Tahasal ala rabit t.me mithl https://t.me/your_business?start=Marhaban yimkin naskhuh wa musharakathuh wa tahwiluh ila QR. Bila tasjil, bila khawadim, kul shay fi al-mutasaffih.',
    'tgl.seo.use.heading': 'Ayn istikhdam rabit tilejgram',
    'tgl.seo.use.text': 'Rabitat tilejgram mutada istikhdamat. Fi banar instghram — ahad al-amakan al-akthar shuyuan. Ala safha ittisal al-mawqi. Fi tawqiat al-barid. Ibtih QR ala bitaqat al-amal wa al-kutayib. Istakhdim li al-buat liyabdaa al-mustakhdimun bi amr muhadid. Al-ihimalat la hudud laha.',
    'tgl.seo.faq.heading': 'Al-asila al-shaia',
    'tgl.seo.faq.q1': 'Hal insha rabit tilejgram majani?',
    'tgl.seo.faq.a1': 'Nam, majani tamanan. OPN Chat yullid rabitat t.me bila taklifa, hudud, tasjil aw iylanat. Al-rabitat tamal daiman — mabniya ala al-burtukul al-rasm li tilejgram.',
    'tgl.seo.faq.q2': 'Ma hi risalat al-bad?',
    'tgl.seo.faq.a2': 'Risalat al-bad hi nas iftiradi yazhar an fath rabit tilejgram. Tashil bad al-muhadatha. Mithal: "Marhaban, arid ma rifat tafasil akthar an khidmatikum." Mufida khasan li buat tilejgram.',
    'tgl.seo.faq.q3': 'Hal yahtaj al-shakhs al-akhar li ma rifat ism al-mustakhdim?',
    'tgl.seo.faq.a3': 'La. An al-nqar rabit t.me, yafth tilejgram muhadatha ma hasabik aw botik bila ma rifat ism al-mustakhdim. Al-rabit yamal ka bab mubashir li bad al-muhadatha.',
    'tgl.seo.faq.q4': 'Hal yimkin taghyr al-rabit lahiqan?',
    'tgl.seo.faq.a4': 'Haykal al-rabit thabit (t.me/USERNAME). An taghyr ism al-mustakhdim, yajib insha rabit jadid. Risalat al-bad yimkin taghyrha bi insha rabit jadid bi nas mukhtalif.',
    'tgl.seo.faq.q5': 'Hal yamal li al-buat wa al-qanawat aydan?',
    'tgl.seo.faq.a5': 'Nam! Rabitat t.me tamal li al-hasabat al-shakhsiya wa al-buat wa al-qanawat. Li al-buat, muamil ?start= qawi jidan — yati al-mustakhdimun bad al-bot bi amr muhadid, mithali li al-tawjih wa khidmat al-amilin.',
