    'cw.preview.label': 'معاينة الودجت',
    'cw.seo.what.heading': 'ما هو ودجت دردشة واتساب?',
    'cw.seo.what.text': 'ودجت دردشة واتساب هو زر عائم أو نافذة منبثقة تظهر على موقعك، تتيح للزوار بدء محادثة واتساب معك بنقرة واحدة. عند نقر الزائر على الودجت، يفتح واتساب برسالة مُعبأة مسبقاً جاهزة للإرسال — دون الحاجة لحفظ رقمك أولًا. الودجت يظهر كبزر دائري صغير في زاوية الموقع يتوسع إلى نافذة دردشة مع رسالة ترحيب. مولّد OPN Chat يتيح إنشاء هذا الودجت مجاناً، تخصيص مظهره وسلوكه، والحصول على مقطع كود HTML جاهز للاستخدام.',
    'cw.seo.why.heading': 'لماذا تضيف ودجت واتساب لموقعك?',
    'cw.seo.why.feature1.title': 'تواصل فوري مع العميل',
    'cw.seo.why.feature1.desc': 'الزوار يمكنهم التواصل معك بنقرة واحدة. لا حاجة لحفظ رقم أو ملء نموذج — فقط انقر وابدأ الدردشة على واتساب.',
    'cw.seo.why.feature2.title': 'قابل للتخصيص بالكامل',
    'cw.seo.why.feature2.desc': 'اختر لون الودجت وموضعه ورسالة الترحيب ونص الزر. اجعله يتناسب مع علامتك التجارية تماماً. كل تفصيلة قابلة للإعداد.',
    'cw.seo.why.feature3.title': '100% مجاني وخصوصي',
    'cw.seo.why.feature3.desc': 'لا رسوم شهرية، لا مستويات مدفوعة، لا جمع بيانات. كود الودجت يُولّد كلياً في متصفحك ويعمل على موقعك بشكل مستقل.',
    'cw.seo.why.feature4.title': 'يعمل على أي موقع',
    'cw.seo.why.feature4.desc': 'انسخ كود HTML وألصقه في WordPress أو Shopify أو Wix أو Squarespace أو Blogger أو أي موقع مخصص. لا حاجة لإضافات أو امتدادات.',
    'cw.seo.how.heading': 'كيف يعمل',
    'cw.seo.how.text': 'إنشاء ودجت دردشة واتساب مع OPN Chat يستغرق أقل من دقيقة. أدخل رقم واتساب مع رمز الدولة، أضف رسالة مُعبأة مسبقاً، اختر الموضع (يسار أو يمين)، حدد اللون، اكتب رسالة الترحيب وعيّن نص الزر. انقر «توليد كود الودجت» — تحصل على مقطع HTML كامل. انسخه وألصقه في HTML الموقع قبل علامة body الختامية، والودجت يظهر فوراً. بدون تسجيل أو تخزين على الخوادم.',
    'cw.seo.use.heading': 'أين تستخدم ودجت واتساب',
    'cw.seo.use.text': 'ودجتات دردشة واتساب مثالية لأي موقع يريد تسهيل التواصل مع العملاء. متاجر Shopify أو WooCommerce تستخدمها لاستفسارات المنتجات ودعم الطلبات. خدمات مثل عيادات الأسنان والمحامين ووكلاء العقارات تضعها على الصفحات الرئيسية. المطاعم والمقاهي تضمّنها لطلبات الحجز. الفنادق ووكالات السفر تستخدمها لتأكيد الحجوزات واستفسارات النزلاء. مدونات WordPress ومواقع الملفات الشخصية تضيفها لتفاعل القراء. الودجت يعمل على كل المنصات التي تسمح HTML.',
    'cw.faq.heading': 'أسئلة شائعة',
    'cw.faq.q1': 'هل ودجت واتساب مجاني?',
    'cw.faq.a1': 'نعم، مجاني تماماً. OPN Chat يولّد كود الودجت بلا تكلفة، بلا حدود، بلا تسجيل، بلا إعلانات. الكود يعمل على موقعك بشكل مستقل — لا تبعيات خارجية أو رسوم شهرية.',
    'cw.faq.q2': 'هل أحتاج لتركيب إضافة?',
    'cw.faq.a2': 'لا. فقط انسخ مقطع كود HTML وألصقه في موقعك. يعمل على WordPress و Shopify و Wix و Squarespace و Blogger و أي موقع يسمح تعديل HTML. بلا إضافات أو امتدادات أو إعداد خادم.',
    'cw.faq.q3': 'هل يمكنني تخصيص مظهر الودجت?',
    'cw.faq.a3': 'نعم. يمكنك اختيار موضع الودجت (يسار أو يمين)، لون الزر، نص رسالة الترحيب وعلامة الزر. كل التخصيصات تُنفذ في المولّد والكود النهائي يعكس خياراتك بالضبط.',
    'cw.faq.q4': 'هل يعمل الودجت على الأجهزة المحمولة?',
    'cw.faq.a4': 'نعم. على الأجهزة المحمولة، النقر على الودجت يفتح تطبيق واتساب مباشرة. على الحاسوب يفتح واتساب ويب. الودجت يتكيف تلقائياً مع جهاز الزائر.',
    'cw.faq.q5': 'هل يجمع الودجت بيانات?',
    'cw.faq.a5': 'لا. كود الودجت من OPN Chat هو HTML و CSS و JavaScript خالص على جانب العميل. لا يرسل أي بيانات إلى OPN Chat أو خوادم خارجية. عند النقر يذهب الزائر مباشرة إلى واتساب عبر البروتوكول الرسمي wa.me.',
    'cw.footer.tagline': 'opnchat.net — مولّد ودجت دردشة واتساب. لا بيانات على الخوادم. كل شيء يعمل في المتصفح.',
    'cw.footer.disclaimer': 'OPN Chat غير مرتبط بMeta أو واتساب.',
