    'ep.seo.what.text': 'منتقي الإيموجي (أو لوحة مفاتيح الإيموجي) هو أداة مجانية على الإنترنت تمكنك من البحث، تصفح، ونسخ أي رمز إيموجي مباشرة إلى الحافظة. بخلاف منتقي الإيموجي المدمج في هاتفك أو حاسوبك، والمحدود بالتطبيقات التي تستخدمها حالياً، منتقي الإيموجي في OPN Chat يعمل في أي متصفح على أي جهاز. فقط ابحث عن الإيموجي المطلوب بالتصفح عبر الفئات أو كتابة كلمة مفتاحية، اضغط عليه، وينسخ فوراً إلى الحافظة — جاهز للصق في واتساب، تيليجرام، إنستغرام، تويتر/X، تيك توك، البريد الإلكتروني أو أي حقل نصي. الكatalog يضم أكثر من 500 إيموجي مصنفين في 9 فئات، كل منها قابل للبحث بالاسم والكلمة المفتاحية.',
    'ep.seo.why.heading': 'لماذا تستخدم منتقي إيموجي على الإنترنت?',
    'ep.seo.why.feature1.title': 'البحث بالكلمة المفتاحية',
    'ep.seo.why.feature1.desc': 'اكتب "قلب"، "قطة" أو "نار" واعثر على الإيموجي المثالي فوراً. لا حاجة للتنقل عبر مئات الإيموجي — البحث يفلتر في جميع الفئات الـ 9 في آن واحد، ويعرض كل إيموجي يطابق استفسارك.',
    'ep.seo.why.feature2.title': 'نسخ ولصق في أي مكان',
    'ep.seo.why.feature2.desc': 'ضغطة واحدة تنسخ الإيموجي إلى الحافظة. ألصقه مباشرة في رسائل واتساب، محادثات تيليجرام، السيرة والتعليقات في إنستغرام، منشورات تويتر/X، تعليقات تيك توك أو أي منصة. الإيموجي هي رموز Unicode قياسية، لذلك تعمل في كل مكان.',
    'ep.seo.why.feature3.title': '100% خاص',
    'ep.seo.why.feature3.desc': 'منتقي الإيموجي في OPN Chat يعمل كلياً في متصفحك. لا يتم رفع أي اختيار إيموجي، لا تُخزّن بيانات على أي خادم، ولا تُستخدم كوكيز للتتبع. سجل تصفح الإيموجي محفوظ محلياً في المتصفح فقط لسهولة الوصول — يمكنك حذفه في أي وقت.',
    'ep.seo.why.feature4.title': 'يعمل على أي جهاز',
    'ep.seo.why.feature4.desc': 'منتقي الإيموجي يعمل على الهواتف، الأجهزة اللوحية والحواسيب. على الهاتف، يستبدل لوحة الإيموجي المدمجة المحدودة بكatalog قابل للبحث. على الحاسوب، يتيح الوصول إلى الإيموجي عندما لا تملك لوحة إيموجي مدمجة في الكيبورد. لا يتطلب تثبيت أي تطبيق.',
    'ep.seo.how.heading': 'كيف يعمل منتقي الإيموجي?',
    'ep.seo.how.text': 'استخدام منتقي الإيموجي في OPN Chat سهل. تصفح الإيموجي بالضغط على أحد tabs الفئات الـ 9 (رموز تعبيرية، أشخاص، حيوانات، طعام، أنشطة، سفر، أشياء، رموز، أعلام)، أو اكتب كلمة مفتاحية في خانة البحث لإيجاد الإيموجي في جميع الفئات. عندما ترى الإيموجي الذي تريده، اضغط عليه — الإيموجي ينسخ فوراً إلى الحافظة وإشعار مختصر يؤكد النسخ. ألصقه في أي تطبيق أو حقل نصي. الإيموجي المستخدمة مؤخراً محفوظة محلياً في المتصفح لتتمكن من إيجادها بسرعة مرة أخرى.',
    'ep.seo.faq.heading': 'الأسئلة الشائعة',
    'ep.faq.q1': 'هل تعمل الإيموجي في واتساب وتيليجرام?',
    'ep.faq.a1': 'نعم! كل الإيموجي في هذا المنتقي هي رموز Unicode قياسية، يدعمها واتساب، تيليجرام، إنستغرام، تويتر/X، تيك توك، فيسبوك، SMS، البريد الإلكتروني وجميع المنصات تقريباً. عند نسخ إيموجي من OPN Chat ولصقه في واتساب أو تيليجرام، يظهر بالضبط كما هو مقصود على جهازك وجهاز المستلم.',
    'ep.faq.q2': 'هل منتقي الإيموجي مجاني?',
    'ep.faq.a2': 'مجاني تماماً. بدون تسجيل، بدون مستويات مميزة، بدون إعلانات، بدون حدود. تصفح وانسخ إيموجي كما تشاء — الأداة متاحة للجميع بدون أي قيود. كل المعالجة تعمل في متصفحك بدون أي تفاعل مع الخادم.',
    'ep.faq.q3': 'هل يتتبع OPN Chat اختيارات الإيموجي?',
    'ep.faq.a3': 'لا. OPN Chat لا يرفع، يسجل أو يتتبع أي اختيار إيموجي. الإيموجي المستخدمة مؤخراً محفوظة فقط في localStorage المتصفح لسهولة الوصول السريع. يمكنك حذف هذا السجل في أي وقت بمسح بيانات المتصفح. لا تُرسل أي معلومات إلى خوادمنا.',
    'ep.faq.q4': 'كم عدد الإيموجي المتاحة?',
    'ep.faq.a4': 'منتقي الإيموجي في OPN Chat يضم أكثر من 500 إيموجي في 9 فئات: رموز تعبيرية ومشاعر (60+)، أشخاص وجسم (70+)، حيوانات وطبيعة (70+)، طعام وشراب (80+)، أنشطة ورياضة (60+)، سفر وأماكن (80+)، أشياء (100+)، رموز (90+)، وأعلام (80+). الكatalog يشمل الإيموجي الأكثر استخداماً للمراسلة ووسائل التواصل.',
    'ep.faq.q5': 'هل يمكنني البحث عن الإيموجي بالكلمة المفتاحية?',
    'ep.faq.a5': 'نعم! اكتب أي كلمة مفتاحية في خانة البحث — مثلاً "قلب"، "قطة"، "نار"، "سعيد"، "طعام"، "سيارة" — والمنتقي يفلتر جميع الإيموجي في كل فئة تطابق البحث. كل إيموجي مرتبط بكلمات مفتاحية متعددة، فحتى إذا لا تعرف الاسم الدقيق، كلمة ذات صلة ستعثر عليه.',
    'footer.emojipicker.link': 'منتقي الإيموجي',

